(window.NTDATA=window.NTDATA||{});(NTDATA.rbo=NTDATA.rbo||{}).jer={"1":{"1":"Вот слова Иеремии, сына Хилкии, из священников Анатота, что в земле Вениаминовой.","2":"Господь возвестил ему Свое слово в тринадцатый год правления царя Иудеи Иосии, сына Амона.","3":"И во времена царя Иудеи Иоакима, сына Иосии, Господь возвещал Иеремии Свое слово, и позже, вплоть до одиннадцатого года правления царя Иудеи Седекии, сына Иосии, до пятого месяца, когда жители Иерусалима были угнаны в плен.","4":"Было мне слово Господа:","5":"«Прежде, чем я дал тебе облик во чреве, я избрал тебя, прежде, чем вышел ты из утробы, я пророком поставил тебя для народов».","6":"я ответил: «о Господь, Бог! я говорить не умею, ведь я молод».","7":"И сказал мне Господь: «Не говори, что ты молод! Куда бы я тебя ни отправил, ты пойдешь, все, что я тебе повелю, ты скажешь!","8":"Никого не страшись, я с тобою, я спасу тебя», – говорит Господь.","9":"Простер Господь руку, уст моих коснулся. И сказал мне Господь: «я вложил Мое слово тебе в уста.","10":"Смотри, я сегодня тебя назначил над племенами и царствами – искоренять и разрушать, губить и крушить, строить и насаждать!»","11":"Было мне слово Господа: «Что ты видишь, Иеремия?» я ответил: «Вижу миндалевый жезл».","12":"И сказал мне Господь: «Ты правильно видишь, ибо я готовлюсь слово Мое исполнить».","13":"Снова было мне слово Господа: «Что ты видишь?» я ответил: «Вижу кипящий котел, с севера он нависает».","14":"И сказал мне Господь: «С севера беда нахлынет на всех жителей этой земли!","15":"Ибо Я призову все народы северных царств, – говорит Господь. – Придут они, престолы свои поставят возле ворот Иерусалима, вокруг его стен, повсюду, у всех городов Иудеи.","16":"Над нею Я суд устрою за все ее злодеянья, за то, что Меня оставила, богам иным воскуряла, твореньям рук своих поклонялась.","17":"А ты – препояшься, встань, говори людям все, что Я тебе повелю. Испугаешься их – погублю тебя перед ними!","18":"Я сегодня тебя поставил неприступным градом, столпом железным, стеною медной – против всей этой земли, против царей и вельмож Иудеи, против священников, против народа земли этой.","19":"На тебя они ополчатся, но будут пред тобою бессильны, ибо Я с тобою, – говорит Господь, – Я спасу тебя»."},"2":{"1":"Было мне слово Господа:","2":"иди в Иерусалим, объяви во всеуслышание столице: Так говорит Господь: «Я помню, в юности ты была верной, как невеста, Меня любила, ты шла за Мной по пустыне, по землям бесплодным.","3":"Израиль – святыня Господа, начаток Его урожая! Всякого, кто на него покусится, ждет кара, беда настигнет», – говорит Господь.","4":"Слушайте слово Господа, потомки Иакова, все племена Израиля!","5":"Так говорит Господь: «Какую же вину нашли за Мной ваши отцы? Почему от Меня отдалились? За тщетой пустой они устремились – и сами стали тщетой пустою.","6":"Не искали они Господа, не говорили: „Он вывел нас из Египта, Он вел нас в пустыне, в краю ущелий безводных, зноя и тьмы кромешной, где человек не ходил, где никто не селился\".","7":"Я привел вас на тучную землю, чтобы вы насладились хорошими ее плодами. Но пришли вы – и землю Мою осквернили, достоянье Мое сделали мерзостью!","8":"Не ищут Господа священники, не знают Меня знатоки Закона, ваши пастухи против Меня восстали, именем Ваала вещают пророки. Поклоняетесь вы идолам бесполезным!","9":"Я за это на суд призову вас, – говорит Господь, – на суд призову ваших детей и внуков!","10":"В края киттеев отправляйтесь, смотрите, в Кедар пошлите послов, разведайте и узнайте, бывало ли где такое?","11":"Меняют ли своих богов народы? А ведь эти боги – не Бог. Мой же народ променял свою Славу на идолов бесполезных.","12":"О небеса, ужаснитесь этому, от ужаса содрогнитесь! – говорит Господь. –","13":"Два преступленья Мой народ совершил: он оставил Меня, живой воды Источник, а себе искусственные водоемы сделал. Водоемы эти растрескаются, воды удержать не смогут.","14":"Разве Израиль – раб, слуга, рожденный в неволе? Почему же он стал добычей?","15":"Молодые львы на него рычат громким рыком, превратили землю его в пустыню, города его сожжены, безлюдны.","16":"Жители Нофа и Тахпанхеса голову тебе разбили!","17":"Не ты ли сама в том виновна? Господа, Бога твоего, ты оставила, когда Он вел тебя по дороге!","18":"А ныне – что же идешь ты в Египет пить воду Шихора? Что же идешь в Ассирию пить воду Евфрата?","19":"Твое злодеяние тебя накажет, обличит – твоя же измена. Знай, смотри: на беду и горе Господа, Бога твоего, ты оставила, страх предо Мной потеряла, – говорит Господь, Бог Воинств. –","20":"В древности Я разбил ярмо твое, разорвал твои путы. И сказала ты: „Другим я служить не буду!\" Но на всех холмах высоких, под каждым деревом ветвистым ты развратничаешь, блудница!","21":"Я заботился о тебе, как о винограднике лучшем, отборных побегах. Но горе! Для Меня ты стала лозою дикой.","22":"Не отмыться тебе ни щелочью, ни мылом! Грязь греха твоего – предо Мною! – говорит Господь Бог. –","23":"Неужели ты скажешь „чиста я, к Ваалам я не ходила\"? Посмотри на дела свои в долине, пойми, что ты совершила! Верблюдица молодая мечется по дорогам,","24":"дикая ослица, выросшая в пустыне, задыхается от страсти! Пыл ее кто умерит? Всякий, кто ее вожделеет, без труда ее отыщет в пору случки.","25":"Берегись, чтоб не стать тебе босою, чтобы горло твое не пересохло! Но подумала ты: „Пустое! Чужаков люблю я, к ним ходить буду\".","26":"Словно вор, что пойман с позором, опозорен Израиль – народ, цари и вельможи, священники и пророки.","27":"Дереву они говорят „отец мой\", камень зовут „мать моя\". Не лицом ко Мне повернулись, а спиною. Но беда нагрянет – скажут: „Спаси нас!\"","28":"Где же боги ваши, которых вы сотворили? Пусть спасают вас, если могут, когда беда нагрянет! В каждом городе твоем, Иудея, свой бог найдется.","29":"Вам ли судиться со Мною? Вы все предо Мной виновны, – говорит Господь. –","30":"Сыновей ваших карал Я тщетно, наставленье они отвергли! Меч ваш пожрал пророков ваших, как лев беспощадный.","31":"О вы, живущие ныне, слово Господа поймите! Разве Я для Израиля был пустыней, землею мрака? Почему же народ Мой сказал: „Мы пойдем, куда пожелаем, к Тебе не вернемся\"?","32":"Разве может девица забыть наряды, невеста – свои уборы? А Меня Мой народ позабыл давным – давно.","33":"Как искусно ты умеешь домогаться любви, в этом и худших женщин наставить можешь!","34":"На твоей одежде – кровь бедняков невинных! Разве застала ты их за кражей? Но при этом","35":"ты говоришь: „Я невиновна! Его гнев меня минует\". Я тебя призову к ответу за слова твои „я не грешила\"!","36":"Что же бродишь ты непрестанно, то в одну сторону, то в другую? И Египет тебя опозорит, как Ассирия осрамила!","37":"и оттуда уйдешь ты, голову обхватив руками. Ибо Господь отверг тех, на кого ты уповала: не будет тебе удачи с ними!"},"3":{"1":"Если муж жену прогонит и она его покинет, уйдет к другому мужу, разве первый муж к ней вернется? Разве не осквернилась бы от этого страна? Ты блудила с толпой народа, но вернись ко Мне! – говорит Господь. –","2":"Посмотри на холмы пустые: есть ли место, где ты не блудила? Путников ты ждала у дороги, словно араб в пустыне. Осквернила ты землю развратом своим и злодейством!","3":"Потому дождей не стало, весенний не льется ливень! У тебя – лицо блудницы, ты стыд позабыла.","4":"А теперь ты Мне говоришь: „Отец мой! Юности моей Наставник!","5":"Неужели вечно Он гневаться будет, будет всегда в ярости?\" Говоришь ты так, но творишь, сколько можешь, злодейства!»","6":"Сказал мне Господь во дни царя Иосии: «Ты ведь видел, что творила дочь Израиля, изменница, как ходила она ко всякой горе высокой, к каждому дереву ветвистому и блудила там.","7":"И после всего, что она совершила, Я сказал: „Вернись ко Мне!\" Но она не вернулась. И вероломная сестра ее Иудея это видела.","8":"За то, что развратничала дочь Израиля, изменница, Я прогнал ее и дал ей разводное письмо. И увидел Я, что сестра ее, вероломная Иудея, не испугалась, но сама отправилась блудить.","9":"Безудержным своим развратом она осквернила землю, прелюбодействовала с камнем и деревом.","10":"И вот, не от чистого сердца вернулась ко Мне вероломная сестра ее Иудея, а лишь притворяясь», – говорит Господь.","11":"И сказал мне Господь: «Дочь Израиля, изменница, честнее, чем вероломная Иудея.","12":"Ступай, возвести северу такие слова, скажи: Вернись, изменница, дочь Израиля! – говорит Господь. – Гнева Моего на тебя не обрушу, ибо Я милостив, – говорит Господь, – не вечно гневаться буду.","13":"Лишь признай свое преступленье: против Господа, Бога твоего, ты грешила, ласки свои чужакам расточала под каждым деревом ветвистым, Мне не повиновалась, – говорит Господь.","14":"Вернитесь, дети – отступники, – говорит Господь, – ибо Я Владыка ваш! Я возьму вас, по одному из каждого города, по двое из каждого племени, и приведу вас на Сион.","15":"Я дам вам пастухов, угодных Моему сердцу, чтобы они пасли вас мудро и разумно.","16":"В те дни, когда вы размножитесь и расплодитесь на этой земле, – говорит Господь, – о ковчеге договора Господнего говорить уже не будут, не будут о нем думать и вспоминать его, не будут тосковать о нем и другого ковчега не сделают.","17":"В то время назовут Иерусалим престолом Господним, и все народы соберутся в Иерусалим – туда, где обитает имя Господа. Не будут они больше поступать по упрямству злых своих сердец.","18":"В те дни потомки Иуды и потомки Израиля соберутся вместе и уйдут из страны северной в ту землю, которую Я даровал вашим отцам».","19":"…И сказал Я: «Как же буду считать тебя сыном, как дам тебе желанную землю, удел прекрасный, красу народов? Я думал, ты звать Меня будешь „Отец мой\", от Меня не отступишь.","20":"Но, как жена изменяет мужу, так и ты изменил Мне, Израиль!» – говорит Господь.","21":"Стон над холмами раздается, плач и мольба сынов Израиля, ибо с пути своего они свернули, Господа, Бога своего, забыли.","22":"«Вернитесь, дети – отступники, Я исцелю неверность вашу!» Вот, к Тебе мы приходим, ибо Ты – Господь, Бог наш!","23":"Ведь на холмах – лишь обман, на горах – только шум сборищ. Воистину, лишь в Господе, Боге нашем, спасенье Израиля!","24":"С юности нашей Мерзость пожирала труды отцов наших, овец и коров их, сыновей и дочерей.","25":"В мерзостях своих мы погрязли, позором покрыты! Ибо мы грешили против Господа, нашего Бога, мы и отцы наши, с юности нашей и доныне. Мы не повиновались голосу Господа, нашего Бога!"},"4":{"1":"«Если ты, Израиль, вернешься, – говорит Господь, – если ко Мне вернешься, мерзости свои предо Мной отринешь, блуждать перестанешь,","2":"если ты поклянешься истинно, справедливо и праведно: „Жив Господь!\" – тогда благословятся тобою народы, тебя станут прославлять!»","3":"Ибо так говорит Господь людям Иудеи, Иерусалиму: «Пашню новую себе вспашите, среди терний не сейте!","4":"Ради Господа сделайте себе обрезанье, обрезанье сердца совершите, люди Иудеи, жители Иерусалима, – чтобы ярость Моя не разгорелась, как пламя, как пожар, который никто не потушит, за все злодеяния ваши.","5":"Расскажите в Иудее, в Иерусалиме поведайте, возвестите, по всей стране в рог трубите, во весь голос кричите, говорите: „Пойдем, соберемся в городах укрепленных!\"","6":"Знак Сиону подайте, бегством спасайтесь, не стойте, ибо с севера приведу Я горе, великие беды!","7":"Поднимается лев из чащи, губитель народов в путь пустился, из логова своего вышел, чтобы землю твою превратить в пустыню: города твои будут разрушены, жителей в них не останется.","8":"Потому оденьтесь в дерюгу, рыдайте и плачьте, ибо нас не минует яростный гнев Господень.","9":"В тот день, – говорит Господь, – сердце царя будет трепетать от страха, и сердца вельмож, священники в ужасе будут, пророки оцепенеют».","10":"И сказал я: «О Господи, Боже! Неужели сказал Ты неправду этому народу, жителям Иерусалима, обещав им, что мир наступит? Неужели меч поразит их насмерть?»","11":"В то время сказано будет этому народу, жителям Иерусалима: «Ветер жгучий с голых холмов пустыни налетит на дочь Моего народа! На таком ветру зерна не провеять, от мякины зерно не очистить –","12":"слишком он сильный! По воле Моей он примчится – вот тогда Мой суд Я совершу над ними!»","13":"Поднимается он, подобно туче, колесницы его – как вихрь, его кони быстрее орлов! Горе нам, мы погибли!","14":"Иерусалим, очисти свое сердце от зла, тогда спасешься! Сколько будешь еще лелеять злые мысли?","15":"Раздается крик из Дана, весть о гибели – с гор Ефрема.","16":"Объявите о том народам, расскажите в Иерусалиме: идут полчища из страны далекой, над городами Иудеи клич их раздается!","17":"Словно стражи полей, обступили они столицу. «Ведь против Меня она восстала! – говорит Господь. –","18":"Дела твои и поступки тебе принесли все это! Злодейство твое – вот причина, что ты истерзана горем».","19":"О сердце, сердце! Изнемогает сердце от боли, рвется оно на части, не знаю покоя. Ибо голос труб душа моя слышит, боевые кличи!","20":"Беда за бедой приходит, вся страна разграблена. Пали шатры внезапно, жилища – в мгновенье ока.","21":"Доколе мне видеть знамена, слышать голос труб?","22":"«Мой народ безрассуден, Меня не знает! Словно глупые дети, разума они не имеют, умны они лишь на злодейство, добро творить не умеют».","23":"Я посмотрел на землю – она безвидна и пуста, взглянул на небо – нет там света.","24":"Я посмотрел на горы – они дрожат, все холмы трепещут.","25":"И увидел я, что ни единого нет человека, разлетелись небесные птицы.","26":"Увидел я: цветущий край превратился в пустыню, каждый город его разрушен по воле Господа – вот Его гнев и ярость!","27":"Так говорит Господь: «Вся земля эта станет пустыней, полностью ее уничтожу!","28":"Потому земля зарыдает, почернеет высокое небо: Я произнес решенье – не передумаю, его исполню.","29":"Всадники и лучники кричат, жителей городов обращают в бегство. Убегают жители в чащи, уходят в горы. Все города опустели, ни души там не осталось.","30":"А ты, истерзанная! Что станешь делать? Одевалась ты в пурпур, наряжалась в наряды золотые, подводила глаза сурьмою. Но напрасно ты прихорашивалась! Те, кто блудил с тобою, ныне тебя отвергли, смерти твоей желают».","31":"Крики слышу – будто женщина рожает, первенца рожает в муках. Стоны дочери Сиона раздаются, простирает она руки: «Горе мне! Пред убийцами я бессильна!»"},"5":{"1":"«По улицам Иерусалима идите! Смотрите, разузнайте, на площадях ищите: не найдете ли где человека, есть ли где хоть один справедливый, стремящийся к правде – и тогда Я прощу столицу!»","2":"Говорят они: «Жив Господь!» – но клятвы эти лживы.","3":"Око Твое, о Господь, разве не увидит правды? Ты сокрушал их – они не отступились, убивал – не вразумила их кара! Стали они тверже камня, отвергли раскаяние.","4":"И сказал я: «То бедняки, они неразумны, не знают они пути Господнего, справедливых законов Божьих.","5":"Пойду я к знатным, говорить буду с ними, ибо знают они путь Господень, справедливые законы Божьи. Но они тоже ярмо разбили, разорвали узы.","6":"Потому напал на них лев из чащи, волк степной их терзает, у городов леопард караулит: кто из города выйдет – будет разорван в клочья! Ибо велики грехи их, нет числа их изменам».","7":"«Как прощу Я тебя? Твои дети Меня отвергли, богами ложными клянутся! Я питал их – они предались разврату, в домах блудниц толпятся.","8":"Словно сытые жеребцы, они похотливы: каждый ржет призывно, глядя на жену соседа!","9":"Неужели за это их не покараю? – говорит Господь. – Неужели народу такому не отомщу Я?","10":"На стены его взбирайтесь, рушьте, до конца уничтожьте! Сады его разоряйте: он теперь – не народ Господень.","11":"Ибо предали Меня род Израиля и род Иуды! – говорит Господь.","12":"От Господа они отрекались, говорили: „Нет Его! Не придут к нам беды, меча и голода мы не узнаем!\"","13":"Пророки эти – что ветер, не открыто им слово Мое. Пусть это все случится с ними!»","14":"Так говорит Господь, Бог Воинств: «Говорят они слова такие, и потому в уста твои Я вложу Мое слово, как пламя, и станет народ этот дровами, и пожрет его пламя!","15":"О дом Израилев! Я пошлю на тебя народ далекий, – говорит Господь, – народ могучий, народ древний! Языка его ты не знаешь, не поймешь его речь.","16":"Колчан его – как отверстая могила, каждый воин его силен.","17":"Он пожрет урожай твой и хлеб твой, сыновей твоих и дочерей, овец и коров пожрет он, и виноград, и смоквы. Он мечом разобьет твои твердыни, на которые ты уповаешь.","18":"Но даже в те дни, – говорит Господь, – не до конца истреблю вас.","19":"И когда спросят: „За что Господь, Бог наш, сделал нам все это?\" – ответь им: „Вы оставили Его и служили на своей земле чужим богам, потому вы будете служить чужеземцам – на чужой земле\".","20":"Потомкам Иакова о том объявите, поведайте Иудее.","21":"Слушай, глупый народ, лишенный разума! Есть глаза у них, но не видят, уши есть, но не слышат!","22":"Не Меня ли должны вы бояться, – говорит Господь, – трепетать предо Мною? Я песок положил границей морю, пределом вечным, за который морю не выйти. Волны морские бушуют, но предела одолеть не могут, шумят, но его не переходят.","23":"А народ этот – упрям и непокорен: отвернулись они, ушли прочь.","24":"В сердце своем не говорили: „Устрашимся Господа, нашего Бога, который в срок нам дождь дарует, и осенью, и весною, назначил нам недели для жатвы!\"","25":"Преступления ваши отняли у вас все это, грехи лишили вас блага.","26":"Есть в народе Моем злодеи: хитры они, как птицелов в засаде, сети они расставляют – людей ловят!","27":"Словно клетка, полная птиц, дома их полны коварства. Потому возвеличились они, разбогатели,","28":"растолстели, от жира лоснятся. Творят они любые злодейства, неправедно судят, на тяжбе сироты наживаются, дело бедняка не разбирают.","29":"Неужели за это их не покараю? – говорит Господь. – Неужели народу такому не отомщу Я?","30":"Ужас и мерзость на этой земле творятся:","31":"ложь вещают пророки, с их помощью священники правят, и народу Моему это по сердцу! И после этого что ж с вами будет?"},"6":{"1":"Сыны Вениамина, бегите из Иерусалима! В Текоа в трубу трубите, в Бет – ха – Кереме возвестите, что с севера беда нагрянет, великое горе!","2":"Погублю Я Дочь Сиона, изнеженную и красивую!","3":"Пастухи придут к ней со своими стадами, повсюду шатры поставят, каждый будет пасти на своем уделе».","4":"«Священную войну объявите ей! Вставайте, отправимся в полдень!» – «Увы, день уже на исходе, легли вечерние тени». –","5":"«Вставайте, отправимся в полночь, твердыни ее разрушим!»","6":"Ибо так говорит Господь Воинств: «Деревья рубите, против Иерусалима возводите вал! На город этот обрушится кара – несправедливостью он переполнен.","7":"Как вода клокочет в источнике, так в столице клокочет злодейство, грабеж и насилье в ней не стихают, пред взором Моим – увечья и раны!","8":"Иерусалим! Опомнись, чтобы Я от тебя не отвернулся, не сделал тебя пустыней, землей безлюдной!»","9":"Так говорит Господь Воинств: «Как до ягоды последней виноградник обрывают, так оборвут все то, что в Израиле уцелело. Словно сборщик винограда, протяни руку к ветвям!»","10":"Кому скажу, кого наставлю, кто станет слушать? Внимать они не могут, их уши не слышат. Презирают они, ненавидят слово Господа.","11":"Преисполнен я гневом Господним, удержать его не в силах! «На улице излей его на ребенка, на юношей, собравшихся вместе! И муж и жена попадут в неволю, и старик, чьи дни на исходе.","12":"Дома их достанутся чужеземцам, поля их и жены, ибо Я простираю руку против жителей земли этой, – говорит Господь. –","13":"Все они, от мала до велика, лишь наживы жаждут, от пророка до священника все творят неправду!","14":"Разве они излечат раны Моего народа? Пустословят они: „Мир, мир!\" – но нет мира!","15":"Поступают они постыдно, мерзости совершают, но не думают они стыдиться, смущенья не знают! Потому падут замертво, в час, когда их покараю, повержены будут», – говорит Господь.","16":"Так говорит Господь: «На дорогах встаньте, смотрите, о древних путях расспросите, где путь прямой – по нему идите, и тогда покой для души найдете. Но они отвечали: „Не пойдем!\"","17":"Я поставил для них стражей: „Голосу трубы внимайте!\" Но они отвечали: „Внимать не будем!\"","18":"Потому услышьте, народы, узнай, община, что будет с ними!","19":"Слушай, земля! Ныне Я посылаю беды, на этот народ посылаю плоды его же замыслов, ибо слову Моему они не вняли, Закон Мой отвергли.","20":"Зачем Мне благовония, что везут из Савы, благовонный тростник из страны далекой? Всесожжения ваши Мне неугодны, жертвы ваши Мне неприятны».","21":"Потому так говорит Господь: «Я ставлю этому народу преграды, о них споткнутся отцы с сыновьями, друзья и соседи, споткнутся они и погибнут!»","22":"Так говорит Господь: «Идет народ из страны северной, могучее племя от края земли поднимается!","23":"Лук и меч они держат, жестоки они, беспощадны, их крики – как рокот моря. Скачут они на конях, воины, готовые к битве, – против тебя, дочь Сиона!»","24":"О них услыхали мы вести, руки у нас опустились, боль нас пронзила и мука, словно роженицу.","25":"В поле не выходите, на дорогах не появляйтесь, ибо всюду – враги с мечами, кругом – ужас!","26":"Дочь моего народа! В дерюгу оденься, в пыли катайся, плачь, словно о единственном сыне, стенай горько, ибо внезапно придет к нам губитель.","27":"«Плавильщиком тебя Я сделал, а народ Мой – золотой рудою, чтобы узнал ты цену его поступков.","28":"Все они упрямы и непокорны, живут неправдой. Они – медь и железо, все они порочны.","29":"Раздуваются кузнечные мехи, свинец огнем расплавлен. Но напрасно плавильщик плавил: негодное не отделилось!","30":"Назовут их серебром нестоящим, ибо Господь отверг их»."},"7":{"1":"Вот слово, которое было Иеремии от Господа:","2":"«Встань у ворот Храма Господа и возвести там такое слово, скажи: слушай слово Господа, вся Иудея! Слушайте все, кто входит в эти ворота, чтобы поклониться Господу!»","3":"Так говорит Господь Воинств, Бог Израиля: «Сделайте добрыми ваши пути и деяния, и тогда Я оставлю вас жить на этом месте.","4":"Не доверяйте лживым словам: „Вот он, Храм Господень, Храм Господень, Храм Господень!\"","5":"Если вы сделаете добрыми ваши пути и деяния, если будете вершить правый для каждого суд,","6":"если чужеземца, сироту и вдову не будете притеснять и кровь невинную не будете проливать на месте этом, если не будете поклоняться богам иным во зло себе, –","7":"тогда навечно Я оставлю вас жить на этом месте, на земле, которую Я дал вашим отцам.","8":"Но полагаетесь вы на ложь, и не будет от этого пользы!","9":"Крадете вы, убиваете, прелюбодействуете, клянетесь ложно, воскуряете Ваалу, поклоняетесь богам иным, которых вы не знали,","10":"а потом приходите, встаете предо Мной в этом Храме, который именем Моим осенен, и говорите: „Мы спасены!\" – чтобы и дальше творить все эти мерзости.","11":"Храм, который именем Моим осенен, вы считаете, стал притоном разбойничьим?! Я все это вижу! – говорит Господь. –","12":"Идите же в Силом, на то место, где Я сперва назначил пребывать Моему имени, и посмотрите, что Я сделал с Силомом из-за злодейства Израиля, народа Моего.","13":"А теперь, за то, что вы творите все это, – говорит Господь, – хотя Я говорил вам, говорил снова и снова, но вы не слушали, звал вас, но вы не отвечали, –","14":"за это с Храмом, который именем Моим осенен, с Храмом, на который вы уповаете, с местом, которое Я дал вам и отцам вашим, Я сделаю то же, что и с Силомом!","15":"Я отвергну вас, как отверг ваших братьев, потомков Ефрема.","16":"А ты за народ этот не молись, не плачь о нем, не возноси мольбу, не проси Меня! Я не стану тебя слушать.","17":"Разве не видишь, что творят они в городах Иудеи, на улицах Иерусалима?","18":"Дети дрова собирают, отцы огонь разжигают, женщины месят те – сто, чтобы приготовить жертвенный хлеб Владычице неба! Богам иным возлияния они совершают, чтобы Меня уязвить.","19":"Но Меня ли они уязвят? – говорит Господь. – Самих себя уязвят, себе на позор!»","20":"Потому так говорит Господь Бог: «Яростный гнев Мой изольется на это место, на людей и животных, на деревья полевые и на плоды земли! Будет он пылать, не погаснет».","21":"Так говорит Господь Воинств, Бог Израиля: «Приносите жертвы, всесожжения совершайте, ешьте жертвенное мясо!","22":"Но когда Я вывел вас из Египта, не говорил Я вашим отцам об этом, не давал им заповедей о всесожжениях и жертвах.","23":"Лишь одно Я им заповедал: „Голосу Моему повинуйтесь, и буду Я вашим Богом, вы будете Моим народом. Во всем поступайте так, как Я повелю вам, и будете вы благополучны\".","24":"Но не слушали они, не внимали, поступали по своему разумению, по упрямству злых сердец своих – повернулись ко Мне не лицом, а спиною.","25":"С того дня, когда вышли ваши отцы из Египта, и доныне Я посылал к вам рабов Моих, пророков, посылал снова и снова.","26":"Но не слушали вы Меня, не внимали, сделались вы упрямы, стали еще хуже, чем ваши отцы.","27":"Ты скажешь им все это, но они тебя не послушают, будешь звать их, но они тебе не ответят.","28":"Тогда скажи им: „Вот народ, что не повинуется голосу Господа, Бога Своего, не принимает наставления! Погибла правда, уста этого народа отвергли ее!","29":"Косы свои отрежь и выбрось, огласи холмы похоронным плачем, ибо отверг Господь и покинул поколение это, на которое Он разгневан.","30":"Сыны Иуды творят дела, ненавистные Мне, – говорит Господь. – Они поставили мерзости свои в Храме, который именем Моим осенен, и он теперь осквернен.","31":"Построили они капища в Тофете, что в долине Бен – Хинном, чтобы сжигать своих сыновей и дочерей. Этого Я не заповедовал, сердцу Моему это не угодно.","32":"Потому настанут дни, – говорит Господь, – когда это место будет называться не Тофет и не долина Бен – Хинном, а долина Резни, и для могил в Тофете уже не хватит места.","33":"И трупы людей из этого народа станут пищей для птиц небесных и зверей земных, и некому будет отогнать птиц и зверей.","34":"Я заставлю умолкнуть в городах Иудеи, на улицах Иерусалима голос радости и голос веселья, голос жениха и голос невесты, ибо эта земля обратится в пустыню."},"8":{"1":"В то время, – говорит Господь, – выбросят из могил кости царей Иудеи и кости вельмож, кости священников и пророков, кости жителей Иерусалима.","2":"Разметают их под солнцем и луною, перед всем небесным воинством, которое они любили, которому служили, которому они поклонялись, которое вопрошали, перед которым простирались ниц! И не будут эти кости собраны, погребены не будут – как навоз, они останутся лежать на земле.","3":"А тем, кто выжил, остатку этого племени злого, смерть будет желаннее жизни! Так будет всюду, где они уцелеют, куда бы Я ни изгнал их, – говорит Господь Воинств\".","4":"И скажи им: Так говорит Господь: если упал человек, разве не пытается он подняться? Если сбился с пути, разве не повернет обратно?","5":"Почему же народ этот блуждает, почему Иерусалим блуждает вечно? За ложь они ухватились, раскаяние отвергли.","6":"Я внимал и слушал, но правды они не говорили. Не каялся никто в злодействе, не говорил: „Что же я сделал!\" Каждый из них бежит по своей дороге, словно конь, что по полю боя мчится.","7":"Даже аист в небе свое время знает, голубь, ласточка и журавль в свой срок прилетают. А народ Мой не знает законов Господних!","8":"Что же вы говорите: „Мы мудры, Закон Господень с нами\"? Пишет ложь лживое перо книжников!","9":"Мудрецы позором покрыты, в ужасе они, попались в ловушку. Слово Господа они отвергли – в чем же их мудрость?","10":"Потому их жен Я отдам другим, их поля – иным владельцам. Ведь они, от мала до велика, лишь наживы жаждут, от пророка до священника все творят неправду!","11":"Разве они излечат раны Моего народа? Пустословят они: „Мир, мир!\" – но нет мира!","12":"Поступают они постыдно, мерзости совершают, но не думают они стыдиться, смущенья не знают! Потому падут замертво, в час расплаты повержены будут, – говорит Господь. –","13":"Я уничтожу урожай их, – говорит Господь, – не останется на лозе винограда, на смоковнице не будет смоквы, увянут листья. Все, что Я дал им, пойдет у них прахом».","14":"Что же мы медлим? Пойдем, соберемся в городах укрепленных и там покой отыщем! Господь, Бог наш, судил нам погибнуть, напоил нас водой ядовитой, ведь пред Господом мы грешили.","15":"На мир мы надеялись, но нет блага, исцеления ждали, но пришел ужас!","16":"Слышится из Дана жеребцов хрипенье, от ржанья коней земля содрогнулась! Идут они, пожирают землю и все, что на ней есть, города и жителей их.","17":"«Я на вас посылаю змей ядовитых. Нет от них заклинаний, вас они будут жалить», – говорит Господь.","18":"Горе мое неутешно, сердце мое изнывает!","19":"Слышен зов моего народа из страны далекой: «Неужели Господа нет на Сионе, неужели Царя там нет?» «Для чего они Меня гневили идолами своими, тщетой чужеземной?»","20":"Жатва прошла, кончилось лето, но не пришло к нам спасенье.","21":"От ран моего народа я страдаю! Объял меня мрак, охватил ужас.","22":"Разве нет бальзама в Галааде? Неужели врача там не осталось? Почему же не наступает исцеленье моего народа?"},"9":{"1":"Если б голова моя стала слезами, очи мои – источником слез, я б оплакивал днем и ночью соплеменников моих погибших.","2":"Если бы имел я в пустыне пристанище, я бы народ мой оставил, от него ушел бы. Все они прелюбодеи, предателей стая!","3":"Словно лук натянутый – язык их лживый. Не ради правды на земле сильны они, творят они злодейства одно за другим. «Меня они не знают, – говорит Господь. –","4":"Каждый пусть соседа своего бережется, братьям своим не верьте, ибо брат по пятам крадется, сосед клевету разносит.","5":"Каждый лжет своему соседу, слова правды они не скажут, языки свои во лжи изощрили, отдают греху все силы.","6":"Ты живешь среди коварства! Коварны они, знать Меня не желают», – говорит Господь.","7":"Потому так говорит Господь Воинств: «Переплавлю их, испытаю! Как еще поступить Мне с Моим народом?","8":"Их язык – смертельные стрелы, уста их полны коварства. Пожелают соседу мира, но в сердце готовят ему ловушку.","9":"Неужели за это их не покараю? – говорит Господь. – Неужели народу такому не отомщу Я?»","10":"О горах подниму я плач и стон, о пастбищах степных зарыдаю! Выжжены они, никто по ним не ходит, блеянья стад не слышно. Улетели небесные птицы, звери все разбежались.","11":"«Я сделаю Иерусалим грудой развалин, приютом шакалов, сделаю города Иудеи пустыней, жителей в них не будет».","12":"Кто столь мудр, чтобы понять это? Кто тот человек, с которым говорил Господь и который может возвестить, почему эта земля погибла? Выжжена она, как пустыня, никто по ней не ходит.","13":"И сказал Господь: «За то, что они оставили Мой Закон, который Я дал им, голоса Моего не слушались, ему не повиновались!","14":"Повинуются они упрямым своим сердцам, служат Ваалам, научившись этому у своих отцов».","15":"Потому так говорит Господь Воинств, Бог Израиля: «Накормлю Я народ этот полынью, напою водой ядовитой!","16":"Я рассею их средь народов, которых они не знали – ни они, ни отцы их не знали. Я мечом буду гнать их, до конца уничтожу!»","17":"Так говорит Господь Воинств: «Смотрите! Время звать плакальщиц! Пусть они приходят! За лучшими плакальщицами пошлите, пусть они приходят!»","18":"Пусть они не медлят, плач о нас поднимут! Пусть глаза наши изойдут слезами, пусть потоком истекают очи.","19":"Плач на Сионе слышен: «Горе! Мы ограблены, позором великим покрыты! Мы оставляем землю, разрушены наши жилища».","20":"Слово Господа слушайте, женщины! Пусть ваше ухо слову Его внимает. Дочерей ваших учите плачу, одна другую учите скорбным песням:","21":"«Смерть проникает в окна, в наши покои входит, детей на улицах косит, на площадях – юношей».","22":"И скажи им: так говорит Господь: «Будут валяться трупы, как навоз на поле, словно за жнецом колосья, никем не собраны».","23":"Так говорит Господь: «Пусть мудрец не гордится мудростью, пусть силач не гордится силой, пусть богач не гордится богатством!","24":"Только тот пусть гордится, кто гордится тем, что Меня он знает, Меня ведает. Ибо Я, Господь, Я творю на земле милость и справедливый суд – вот что Мне угодно!» – говорит Господь.","25":"«Настанут дни, – говорит Господь, – когда Я покараю тех, кто обрезан лишь по плоти.","26":"Я покараю Египет и Иудею, Эдом и сынов Аммона, Моав и жителей пустыни, которые бреют себе виски. Другие народы не обрезаны, но и сердце Израиля не обрезано»."},"10":{"1":"Дом Израилев! Слушай слово, которое Господь говорит тебе!","2":"Так говорит Господь: не учитесь путям народов, не страшитесь знамений небесных, которых племена страшатся!","3":"Ведь законы народов ничтожны! Дерево в лесу срубили, мастер топором его обработал,","4":"серебром и золотом его украсил, молотком, гвоздями укрепил, чтобы оно не шаталось.","5":"Словно пугало на грядке огуречной, идолы говорить не могут. Поднимают их, носят, им самим не ступить и шагу. Их не бойтесь, они зла причинить не в силах, и добра от них не будет.","6":"Нет подобного Тебе, о Господь! Ты – Великий! Твое имя – велико и могуче!","7":"Кто Тебя не устрашится, о Царь народов? Одному Тебе это подобает. Среди всех мудрецов разноплеменных, во всех царствах нет подобного Тебе!","8":"Идолы глупы и жестоки! Ученье идолов ничтожных – лишь деревяшка.","9":"Они – серебро чеканное из Таршиша, золото из Уфаза, ремесленника они поделка, плавильщика изделье. Их одежды – лазурь и пурпур, труд искусников.","10":"Лишь Господь Бог – истина, Он – Бог Живой, Царь Вечный, от Его гнева земля сотрясается, перед яростью Его народы бессильны.","11":"Скажите им так: «Не будет больше на земле, под небесами, богов, которые небес и земли не сотворили!»","12":"Могуществом Своим сотворил Он землю, утвердил вселенную мудростью Своею, разумом Своим распростер небо!","13":"Возвысит Он голос – соберутся, зашумят на небесах воды. От края земли Он тучи поднимает, творит Он молнии грозовые и выводит ветер из Своих хранилищ.","14":"Безумен человек без знания, на позор себе мастер идолов выплавляет, ибо изваяния его литые – ложь, нет в них духа.","15":"Ничтожны они, смехотворные поделки, в час расплаты они сгинут.","16":"Но не таков Он, Удел Иакова: всему Он дал облик, Израиль – племя Его и владенье, Его имя – Господь Воинств!","17":"Собирай свои пожитки, чтобы страну свою покинуть, ты, живущая в осаде!","18":"Ибо так говорит Господь: ныне Я изгоню жителей земли этой, на этот раз беду на них обрушу, чтоб они до дна ее испили!","19":"Горе мне! Я истерзан, болят мои раны. И сказал я: «О моя боль! Как ее вынесу?»","20":"Шатер мой разграблен, веревки разорваны. Сыновья ушли, пропали. Кто теперь шатер мой установит, полотнище натянет?","21":"Пастыри безумны стали, Господа не ищут – за это нет им удачи, стада их рассеялись!","22":"Вот весть приходит, из северной земли – гул великий! Станут города Иудеи пустыней, приютом шакалов.","23":"Познал я, Господь: человек над путем своим не властен, идущий не властен над своими шагами.","24":"Накажи меня, о Господь, но справедливо, не во гневе! Не губи меня!","25":"Излей Свою ярость на народы, что Тебя не знают, на племена, что имени Твоего не призывают! Ибо Иакова они пожрали, пожрали его, погубили, селенья его опустошили."},"11":{"1":"Вот слово, которое было Иеремии от Господа:","2":"«Слушайте слова этого договора и возвестите их людям Иудеи, жителям Иерусалима!","3":"Скажи им: „Так говорит Господь, Бог Израиля: проклят всякий, кто не слушает слов договора,","4":"который Я заповедал вашим отцам, когда вывел их из Египта, из печи плавильной! Я сказал им:, Голосу Моему повинуйтесь и во всем поступайте так, как Я повелю вам, и будете вы Моим народом, Я буду вашим Богом'.","5":"Тог – да Я исполню клятву, которую Я дал вашим отцам, – что отдам им землю, текущую молоком и медом, землю, которой вы владеете ныне\"». И я ответил: «Воистину так, о Господь!»","6":"И сказал мне Господь: «Возвести эти слова в городах Иудеи, на улицах Иерусалима. Скажи: „Слушайте слова договора, исполняйте их!","7":"Я предостерегал ваших отцов с того дня, когда вывел их из Египта, и доныне, предостерегал снова и снова. Я говорил им:, Голосу Моему повинуйтесь! '","8":"Но не слушали они, не внимали, каждый поступал по упрямству своего злого сердца. И Я обратил против них все слова этого договора, который Я заповедал им исполнять, но они не исполняли\"».","9":"И сказал мне Господь: «Заговор возник среди людей Иудеи, среди жителей Иерусалима!","10":"Вернулись они к преступлениям своих отцов, которые отказывались слушаться слов Моих, поклоняются они богам иным и служат им. Потомки Израиля и потомки Иуды нарушили договор, который Я заключил с их отцами».","11":"Потому так говорит Господь: «Ныне Я пошлю им беду, избежать которой они не смогут. Воззовут они ко Мне, но Я не услышу их!","12":"И будут города Иудеи и жители Иерусалима с плачем звать богов, которым они воскуряли, но боги эти в час беды ничем не помогут.","13":"В каждом городе твоем, Иудея, свой бог найдется. На каждой улице Иерусалима для мерзости жертвенник вы соорудили, жертвенник – чтобы воскурять Ваалу!","14":"А ты за народ этот не молись, не плачь о нем, не возноси мольбу! Не буду Я слушать, когда они станут звать Меня в своем несчастье.","15":"Что возлюбленной Моей в Моем Храме делать? Творит она множество козней. Неужели жертвенное мясо будет от тебя принято, если злодейству своему ты рада?","16":"Господь дал тебе имя: „Цветущая олива с прекрасными плодами\". Но с громом грозы великой Он послал на нее огонь, и ветви ее погибли.","17":"Господь Воинств, насадивший тебя, предрек тебе беду – за то зло, которое причинили сами себе потомки Израиля и потомки Иуды. Они гневили Меня, воскуряя Ваалу».","18":"Господь мне поведал, потому я узнал! Ты открыл мне их злодейства.","19":"Я был как доверчивый ягненок, вели меня на закланье, и не знал я о кознях, что против меня они замышляли: «Дерево цветущее погубим, чтобы не было его на земле средь живущих, чтобы имя его забыли!»","20":"Но Господь Воинств судит справедливо, испытует душу и сердце. Пусть увижу я, как Ты отомстишь им, ведь Тебе я тяжбу свою доверил!","21":"Потому так говорит Господь о жителях Анатота, которые жаждут твоей смерти и угрожают тебе: «Не пророчествуй именем Господа, иначе мы убьем тебя!» –","22":"так говорит о них Господь Воинств: «Я покараю их ныне! Юноши их от меча погибнут, сыновья их и дочери умрут от голода.","23":"И никто из них не уцелеет, ибо Я пошлю беду жителям Анатота в год кары»."},"12":{"1":"Праведен Ты, Господь, и к Тебе я обращаюсь с тяжбой! Буду говорить с Тобою о справедливости. Почему на путях злодеев – удача, вероломные не знают горя?","2":"Ты насадил их – они пустили корни, разрослись, плоды приносят. Ты у них с языка не сходишь, но далек от их сердца.","3":"О Господь! Ты избрал меня! Посмотри на меня, испытай мое сердце – оно с Тобою. А их, как овец, гони на закланье, избери их для дня бойни.","4":"Доколе земля будет плакать, трава полевая – вянуть из-за злодейства живущих на земле? Исчезли звери и птицы, ибо говорили люди: «Наших путей Он не видит».","5":"Если с пешими ты бежал и сил лишился, как тебе со всадниками тягаться? Если на земле спокойной ты падаешь наземь, что будешь делать в зарослях у Иордана?","6":"Даже братья твои, домочадцы – и они тебя предали, и они тебя провожают криком. Им не верь, даже если доброе слово скажут.","7":"Я оставил Свой Дом, удел Свой покинул, радость души Моей отдал в руки врагов!","8":"Стал удел Мой – словно лев в чаще: он рычит на Меня, потому Я его возненавидел!","9":"Удел Мой – как стервятник пестрый, и стервятники его окружили. Идите, всех зверей полевых соберите! Пусть приходят, будет им, чем поживиться!","10":"Толпы пастухов виноградник Мой разорили, удел Мой вытоптали, превратили удел Мой милый в развалины и пустыню.","11":"Обратили его в пустыню, предо Мной он плачет, опустелый, вся земля стала пустошью, и горевать об этом некому.","12":"По холмам пустыни идут губители, Господень меч пожирает землю, от края до края, плоти живой нигде нет покоя.","13":"Посеяли пшеницу, но терн пожали, измучились – и все без пользы. Ужасайтесь! Нет у вас урожая! Вот яростный гнев Господень!","14":"Так говорит Господь: «Злых Моих соседей, которые посягнули на удел, дарованный Мною народу Мое – му, Израилю, Я вырву из их страны, и род Иуды у них вырву.","15":"Но после того как вырву их, Я вновь смилуюсь над ними и верну каждого в свой удел, каждого в свою землю.","16":"И если они воистину научатся путям Моего народа, будут клясться именем Моим: „Жив Господь!\" – как сами научили Мой народ клясться Ваалом – то укрепятся они среди Моего народа.","17":"А тот народ, что Меня не послушает, Я искореню, искореню его и уничтожу», – говорит Господь."},"13":{"1":"Так сказал мне Господь: «Ступай, купи себе льняную набедренную повязку, опояшься ею и не погружай ее в воду».","2":"Я купил повязку, как велел мне Господь, и опоясался ею.","3":"Вновь было мне слово Господа:","4":"«Возьми повязку, которую ты купил и теперь носишь, иди к Фаре и спрячь ее там в расселине скалы».","5":"Я пошел к Фаре и спрятал там повязку, как велел мне Господь.","6":"Спустя много дней Господь сказал мне: «Иди к Фаре и забери повязку, которую Я велел тебе спрятать там».","7":"Я пошел к Фаре и откопал повязку на том месте, где спрятал ее. И оказалось, что повязка истлела, ни на что не годится.","8":"Было мне слово Господа.","9":"Так говорит Господь: «Вот так же Я заставлю истлеть гордость Иудеи, великую гордость Иерусалима!","10":"О, этот злой народ, который отказывается слушать Мои слова, поступает по упрямству своего сердца, поклоняется богам иным, служит им и простирается ниц перед ними! Будет с ним то же, что и с этой повязкой, которая уже ни на что не годится.","11":"Как повязка прилегает к бедрам человека, так Я прижимал к Себе род Израиля и род Иуды, – говорит Господь, – чтобы они были Моим народом, Моим именем, Моей хвалой и славой, но они не слушали.","12":"Скажи им такое слово: „Так говорит Господь, Бог Израиля: кувшин наполняют вином\". Они ответят тебе: „Разве мы не знаем, что кувшин наполняют вином?\"","13":"Тогда скажи им: „Так говорит Господь: всех жителей этой земли, и царей, восседающих на престоле Давида, и священников, и пророков, и всех жителей Иерусалима, – всех наполню Я пьяным хмелем!","14":"Я разобью их, брата о брата, отцов вместе с сыновьями, – говорит Господь. – Не пощажу их, не пожалею, не помилую, истреблю их!\"»","15":"Слушайте, внимайте, не будьте высокомерны! Ибо Господь сказал это.","16":"Прославьте Господа, вашего Бога, прежде чем тьма наступит, прежде чем вы споткнетесь в горах во мраке! Будете ждать света, но свет Он сделает тьмою, кромешным мраком.","17":"Если вы этих слов не услышите, будет плакать душа моя втайне, рыдать горько о вашей гордыне. Глаза мои изойдут слезами, потому что в плену стадо Господа!","18":"Скажи царю и его матери: «На землю сядьте! Упал с главы вашей венец славы.","19":"Осаждены города Негева, спасти их некому! В плен увели Иудею, пленили всех до единого».","20":"Взгляните, смотрите на тех, кто идет с севера! Где же стадо, что дано тебе было, прекрасные твои овцы?","21":"Что ты скажешь, когда к тебе нагрянут те, кого ты сама научила быть правителями твоими? Муки тебя охватят, словно роженицу!","22":"В сердце своем ты воскликнешь: «За что мне все это?» За бессчетные грехи твои подол твой задрали, над тобой надругались.","23":"Может ли кушит поменять свою кожу, леопард – пятнистую шкуру? Можете ли вы творить благо, лишь злу научившись?","24":"Я разметаю их, как мякину, что кружится на ветру пустыни!","25":"Это жребий твой, удел твой, отмеренный Мною, – говорит Господь, – потому что Меня ты забыла, на ложь уповала.","26":"Вот за это Я сорву твой подол, на лицо тебе наброшу, пусть срам твой увидят!","27":"Разврат твой, ржание похотливое, блуд твой гнусный на холмах пустынных – все мерзости твои Я вижу. Горе тебе, о столица! Доколе ты будешь нечистой?"},"14":{"1":"Вот слово Господа о засухе, которое было Иеремии.","2":"Иудея плачет, врата ее изнывают, лежат на земле, почернели, крик стоит в Иерусалиме!","3":"Вельможи посылают слуг за водою, те приходят к колодцам, но воды не находят – кувшины обратно несут пустыми. В ужасе они, унижены, головы свои покрыли.","4":"Земля вся потрескалась, ибо дожди прекратились. Пахари – в ужасе, головы свои покрыли!","5":"Даже лань полевая детеныша новорожденного бросает, ибо травы не стало.","6":"Дикие ослы стоят на холмах пустынных, хрипят они, как шакалы, глаза их померкли, ибо нет ни травинки.","7":"Преступления наши нас уличают, но вступись, о Господь, ради имени Твоего, хоть измены наши бессчетны и пред Тобой мы грешили!","8":"Надежда Израиля, Избавитель его в час бедствий! Почему же теперь Ты на земле этой – как чужеземец, словно путник, что на ночь остановился?","9":"Почему же теперь Ты – словно человек растерявшийся, словно воин, который спасти не может? Ведь Ты, Господь, – среди нас, имя Твое провозглашено над нами, не оставляй нас!","10":"Так говорит Господь об этом народе: «Бродить они любили, ног своих не щадили, и стали они неугодны Господу. Теперь Он злодейства их вспомнит, за грехи покарает».","11":"Сказал мне Господь: «Не молись о благе для этого народа!","12":"Будут они поститься, но Я не услышу их плача, будут совершать всесожжения и хлебные приношения, но не станут Мне угодны. Я истреблю их мечом, голодом и мором!»","13":"И сказал я: «О Господи, Боже! Вот, твердят им пророки: „Не увидите вы меча, голода у вас не будет, ибо прочный мир Я вам дарую на месте этом\"».","14":"Сказал мне Господь: «Ложь вещают эти пророки от Моего имени! Я не посылал их, не давал им повелений, не говорил с ними. Видения лживые, ворожбу пустую и собственные выдумки они выдают вам за пророчества».","15":"Потому так говорит Господь: «Пророки, которые вещают от Моего имени, хотя Я не посылал их, говорят, что ни меча, ни голода на этой земле не будет, – эти пророки сами от меча и голода погибнут!","16":"И люди, которым они пророчествуют, погибнут от голода и меча, будут лежать на улицах Иерусалима, и некому будет хоронить их, жен их, сыновей и дочерей. Я на них изолью их же зло!","17":"Возвести им это слово. Пусть исходят очи мои слезами, пусть ни днем, ни ночью не перестают плакать, ибо дева, дочь моего народа, изнемогает от ран ужасных, от увечий тяжких.","18":"Выйду в поле – там убитые мечом, приду в город – там измученные голодом. И пророк, и священник по стране блуждают, лишены знания».","19":"Неужели Ты отверг Иудею, неужели Сион душе Твоей ненавистен? Почему же Ты нас терзаешь, почему нам нет исцеленья? На мир мы надеялись, но нет блага, исцеления ждали, но пришел ужас!","20":"Мы знаем, Господь, преступление наше, наших отцов беззаконие, пред Тобой мы грешили.","21":"Но ради имени Твоего не отвергай нас, не обрекай на униженье престол Твоей славы! Вспомни! Не расторгай Твоего договора с нами!","22":"Разве идолы народов дождь посылают? Разве небеса даруют ливень? Разве не Ты – Господь, Бог наш? На Тебя мы уповаем, ибо Ты творишь все это."},"15":{"1":"Сказал мне Господь: «Даже если бы Моисей и Самуил предстали предо Мной, Я и тогда не пожалел бы этот народ. Прогони его прочь от Меня, пусть уходит!","2":"А когда они спросят тебя: „Куда же нам идти?\" – скажи им: Так говорит Господь: кто на смерть обречен, пусть идет на смерть, кто на меч обречен, пусть падет от меча, кто обречен на голод, пусть голодает, кто на плен обречен, пусть в плен уходит!","3":"Я покараю их четырьмя карами, – говорит Господь. – Меч будет убивать их, псы будут рвать их на части, птицы небесные и звери земные будут есть и пожирать их!","4":"Я сделаю их примером страшным для всех царств земли – из-за того, что совершил в Иерусалиме царь Иудеи Манассия, сын Езекии».","5":"Кто тебя пожалеет, Иерусалим? Кто тебя оплакивать станет? Кто подойдет к тебе, тебе посочувствует?","6":"«Ты оставила Меня, о столица, – говорит Господь, – ты ушла прочь. Против тебя Я простер Мою руку, тебя разрушил – жалость Моя иссякла!","7":"Вилами Я развеял их по всем вратам земли. Я оставил народ Мой бездетным, по воле Моей он гибнет, ведь они с пути своего не свернули!","8":"По воле Моей вдов у них стало больше, чем песка морского! Наслал Я на мать юноши грабителей средь бела дня, обрушил на нее внезапно смятенье и ужас.","9":"Родившая семерых теперь бессильна, дух испускает: зашло ее солнце в полдень, опозорена она и поругана. А тех, кто выжил, Я отдам мечу, отдам врагам», – говорит Господь.","10":"О моя мать! Горе мне, что меня ты родила, того, кто тяжбу ведет и спорит со всей землею! Не давал я в рост денег, не брал я в долг, но все меня проклинают.","11":"Сказал Господь: «Я дам тебе свободу для добра! Я заставлю врагов умолять тебя в час беды, в час несчастья.","12":"Кто сломает железо – железо с севера и медь?","13":"Богатства твои и сокровища Я сделаю добычей легкой – за грехи, что ты совершала во всех твоих уделах.","14":"К врагам идти тебя заставлю, в страну, которую ты не знаешь, ибо гнев Мой против вас горит, огнем пылает!»","15":"Ты, Господь, знаешь! Вспомни об мне, позаботься, отомсти за меня гонителям! По терпенью Своему не губи меня, знай – ради Тебя терплю униженья!","16":"Когда слово Твое приходило, оно становилось мне пищей. Для меня слова Твои стали ликованьем и радостью сердца, ибо надо мной провозглашено Твое имя – Господь, Бог Воинств!","17":"Не сижу я в кругу насмешников, не предаюсь веселью – под рукой Твоею сижу одиноко, ибо горечью Ты меня наполнил.","18":"Почему моя боль не проходит, рана моя не заживает, исцелиться не может? Для меня Ты стал потоком пересохшим, водой обманчивой.","19":"И сказал Господь: «Если ты вернешься, Я тебе отвечу, ты предо Мной предстанешь! Если ценное отделишь от пустого, ты устам Моим уподобишься. Люди к тебе вернутся, но ты к ним не возвращайся!","20":"Я поставлю тебя против этого народа неприступной стеною медной. На тебя они ополчатся, но будут пред тобою бессильны, ибо Я с тобою, Я спасу тебя, Я тебя избавлю, – говорит Господь. –","21":"Я избавлю тебя от злодеев, из безжалостных рук вырву!»"},"16":{"1":"Было мне слово Господа:","2":"«Не бери себе жены, и пусть не будет у тебя здесь ни сыновей, ни дочерей».","3":"Ибо так говорит Господь о сыновьях и дочерях, родившихся здесь, о матерях, их родивших, об отцах, от которых они родились на этой земле:","4":"«Мучительной смертью они умрут, не оплачут их, не погребут – как навоз, они останутся лежать на земле. От меча и голода они погибнут, и будут их трупы пищей для птиц небесных и зверей земных».","5":"Так говорит Господь: «Не ходи в дом, где устраивают поминальную трапезу. Не ходи туда плакать и соболезновать, ибо Я отнял мир у этого народа, – говорит Господь, – отнял милость Мою и жалость.","6":"Умрут на этой земле и большие и малые, не будут они погребены: не оплачут их, никто не станет наносить себе порезы и обривать голову в память о них.","7":"Не отломят скорбящим хлеба в утешение об умершем, не напоят их из чаши утешения в память об отце и матери.","8":"И в дом, где устраивают пир, не ходи, не сиди там, не ешь и не пей».","9":"Ибо так говорит Господь Воинств, Бог Израиля: «На ваших глазах, при вашей жизни, Я заставлю умолкнуть в этих местах голос радости и голос веселья, голос жениха и голос невесты.","10":"Когда ты возвестишь этому народу все эти слова, они скажут тебе: „За что Господь предрек нам такое великое горе? В чем преступление наше? В чем наш грех пред Господом, Богом нашим?\"","11":"И скажи им: за то, что ваши отцы оставили Меня! – говорит Господь. – Они поклонялись богам иным, служили им и простирались ниц перед ними, а Меня оставили, Закон Мой не соблюдали.","12":"И вы поступаете еще хуже, чем ваши отцы! Каждый из вас поступает по упрямству своего злого сердца, не слушая Меня.","13":"Потому Я изгоню вас из этой земли в страну, которой не знали ни вы, ни отцы ваши. Там вы будете служить богам иным днем и ночью, ибо Я не пожалею вас.","14":"Но настанут дни, – говорит Господь, – когда не будут уже говорить: „Жив Господь, который вывел сынов Израиля из Египта!\" –","15":"будут говорить иначе: „Жив Господь, который вывел сынов Израиля из земли северной, из всех стран, куда Он изгнал их!\" Ибо Я верну их в страну, которую Я дал их отцам.","16":"Я пошлю множество рыболовов, – говорит Господь, – и они будут ловить их, как рыбу. Потом пошлю множество охотников, и они будут гнать их, как зверей, с каждой горы и с каждого холма, из каждой расщелины в скалах.","17":"Ибо глаза Мои видят путь их, не спрячутся они от Меня – их преступления от глаз Моих не скрыты.","18":"Я вдвойне отплачу им за их преступления и грехи, за то, что они осквернили Мою землю гнусной мертвечиной, мерзостями своими наполнили Мой удел».","19":"Господь – моя сила, моя твердыня, прибежище мое в день несчастья! Придут к Тебе народы со всех концов земли и скажут: «Наследство отцов наших – только ложь, тщета, от которой нет пользы!","20":"Разве может человек богов себе сделать? Ведь эти боги – не Бог!»","21":"«Потому Я покажу им ныне могучую Мою руку, и узнают они, что имя Мое – Господь!"},"17":{"1":"Начертан грех Иудеи стержнем железным, резцом из кремня, на скрижалях сердец их высечен, на рогах жертвенников.","2":"Как о сыновьях своих, о жертвенниках они пекутся, об Ашерах возле дерев ветвистых, на холмах высоких.","3":"Горы твои, богатства твои и сокровища отдам Я на разграбленье, все вершины твои отдам на разграбленье, за грехи, что ты совершала во всех твоих уделах.","4":"По своей вине ты лишишься удела, который Я дал тебе. Я врагам отдам тебя в рабство, в страну, которой ты не знаешь, ибо вы разожгли огонь Моего гнева, и будет пылать он вечно!»","5":"Так говорит Господь: «Проклят тот, кто на человека уповает, плоть считает силой, чье сердце от Господа отвратилось!","6":"Будет он подобен колючему кусту в пустыне, не увидит он блага. Будет он ютиться в пустыне каменистой, на земле соленой и безлюдной.","7":"Благословен тот, кто на Господа уповает, надежда его – Господь!","8":"Будет он подобен дереву, посаженному у воды. У потока оно пустило корни, не боится, что зной наступит. Листва у него густая, год засушливый ему не страшен, плодоносить оно не перестанет.","9":"Коварно сердце человека, оно неисправимо. Кто может знать его?","10":"Я, Господь, Я вижу сердце, испытую душу, чтобы каждому воздать по поступкам, по плодам дел его!»","11":"Сидит куропатка на яйцах, да птенцов не высидит. Так и человек, разбогатевший нечестно, – в расцвете лет он всего лишится, глупцом окажется!","12":"Престол славы, издревле вознесенный, вот место Святыни нашей!","13":"Господь – надежда Израиля! Кто оставил Тебя – посрамится. «Кто отверг Меня, земле достанется, ибо Господа они оставили, живой воды Источник».","14":"Исцели меня, о Господь, и я исцелюсь, спаси меня, и я спасусь, ибо Тебя я славлю!","15":"Вот они говорят мне: «Где же слово Господа? Пусть оно исполнится!»","16":"Не просил я Тебя посылать несчастья, дня беды не жаждал – Ты это знаешь. Слова уст моих – всегда пред Тобою.","17":"Не будь для меня ужасом! Ты – прибежище мое в день бедствия.","18":"Гонители мои пусть посрамятся, а я посрамлен не буду, пусть они ужаснутся, а меня пусть минует ужас! Пошли им день бедствия, сокруши их тяжким ударом!","19":"Сказал мне Господь: «Иди к воротам Вениаминовым, через которые входят и выходят цари Иудеи, иди ко всем воротам Иерусалима –","20":"и говори: слушайте слово Господа, цари Иудеи и вся Иудея, жители Иерусалима, входящие через эти ворота!»","21":"Так говорит Господь: «Чтобы жизни свои сохранить, не берите ношу в день субботний, не носите ее через ворота Иерусалима!","22":"Не выносите ношу из дома в день субботний и никакой работы не делайте. Соблюдайте святость субботы, как Я заповедал вашим отцам,","23":"которые не слушали, не внимали, были упрямы. Не слушали они, не принимали наставления.","24":"Если вы послушаетесь Меня, – говорит Господь, – если не будете проносить ношу через ворота этого города в день субботний, если будете соблюдать святость субботы и никакой работы в этот день делать не станете –","25":"тогда через ворота этого города будут проходить цари, которые восседают на престоле Давида, и вельможи. Будут они проезжать в колесницах и верхом – цари и вельможи их, люди Иудеи и жители Иерусалима. И город этот пребудет вечно.","26":"Будут приходить люди из городов Иудеи, из окрестностей Иерусалима, из земли Вениаминовой, из Шефелы, с гор и из Негева, чтобы совершить всесожжения и жертвоприношения, хлебные приношения и приношения благовоний, чтобы принести благодарственные жертвы в Храме Господа.","27":"Если же вы не послушаетесь Меня, не будете соблюдать святость субботы, будете в день субботний проносить ношу и проходить через ворота Иерусалима, тогда Я сожгу огнем эти ворота! Пожрет дворцы Иерусалима огонь неугасимый!»"},"18":{"1":"Вот слово, которое было Иеремии от Господа:","2":"«Иди в дом гончара, и там Я поведаю тебе Мое слово».","3":"Я вошел в дом гончара и увидел, как он делает свою работу на гончарном круге.","4":"Не получился у него сосуд, который он лепил из глины, и гончар переделал его в другой сосуд – как считал правильным.","5":"Было мне слово Господа:","6":"«Разве Я не могу сделать с тобою, род Израилев, то, что делает этот гончар? – говорит Господь. – Что глина в руках гончара, то и ты – в Моей руке, род Израилев!","7":"Я могу в один миг принять решение о народе или царстве – вырвать его с корнем, повергнуть и уничтожить!","8":"Но если народ, которому Я предрек это, отступит от своего зла, то и Я передумаю, не пошлю бедствие, которое хотел обрушить на этот народ.","9":"Я могу в один миг принять решение о народе или царстве – укрепить его и укоренить!","10":"Но если тот народ совершит зло предо Мною, не станет повиноваться Моему голосу, то и Я передумаю – не пошлю благо, которым хотел одарить его.","11":"Теперь скажи людям Иудеи, жителям Иерусалима: „Так говорит Господь: Я Гончар, Я творю вам беду, против вас Мой замысел! Пусть каждый из вас оставит злой путь свой. Сделайте добрыми ваши пути и деяния\".","12":"Но скажут они: „Пустое! Мы будем делать то, что желаем, все мы будем поступать по упрямству своих злых сердец\".","13":"Потому так говорит Господь: у народов спросите, кто слыхал о таком? Творит ужасное дева Израилева!","14":"Разве покидает скалистые склоны снег Ливана? Разве иссякают горные воды, холодные потоки?","15":"Но Меня народ Мой не помнит, воскуряет богам ничтожным! С пути своего он сбился, с древней дороги, и теперь идет по тропинке, по дороге неровной.","16":"Землю свою он обрек на ужас, на позор вечный! Кто пройдет мимо – ужаснется, головой покачает.","17":"Я, словно ветер восточный, рассею их пред врагами, не лицом обращусь к ним, а спиною в день их бедствия».","18":"Но они сказали: «Пойдем, сговоримся против Иеремии, чтобы Закон оставался у священников, совет – у мудрецов, слово – у пророков! Пойдем, оклевещем его и не станем слушать ни единого его слова!»","19":"Услышь меня, о Господь! И врагов моих послушай!","20":"Неужели за добро платят злом? Мне на погибель они вырыли яму. Вспомни: я стоял пред Тобою, просил для них блага, чтобы отвести от них Твою ярость.","21":"Потому обреки детей их на голод, на острие меча брось их! Жены их пусть овдовеют, детей лишатся, мужей пусть смерть настигнет, пусть юноши на войне от меча погибнут!","22":"Из домов их пусть стоны раздаются, когда Ты приведешь внезапно на них полчища. Ибо они вырыли яму, чтобы поймать меня, сеть для ног моих расставили!","23":"Ты, Господь, знаешь, что они против меня замышляют, мне на погибель. Не прощай им преступлений, на грехи их не закрывай очи! Пусть повержены пред Тобою будут – так поступи с ними в час Твоего гнева!"},"19":{"1":"Так говорит Господь: «Иди, купи у гончара глиняный кувшин. Возьми с собою нескольких старейшин этого народа и нескольких старших священников,","2":"выйди к долине Бен – Хинном, за Горшечные ворота, и провозгласи там слова, которые Я скажу тебе.","3":"Скажи: слушайте слово Господа, цари Иудеи, жители Иерусалима!» Так говорит Господь Воинств, Бог Израиля: «Я пошлю такую беду на это место, что у каждого, кто о ней услышит, зазвенит в ушах!","4":"Ибо жители Иерусалима оставили Меня, осквернили это место, воскуряют здесь богам иным, которых не знали ни они, ни их отцы, ни цари Иудеи, и залили они это место кровью невинных.","5":"Построили они капища Ваалу, чтобы сжигать своих детей в огне как жертву всесожжения Ваалу. Я этого не заповедовал и не повелевал, сердцу Моему это не угодно!","6":"И потому настанут дни, – говорит Господь, – когда это место будет называться не Тофет и не долина Бен – Хинном, а долина Резни!","7":"На этом месте Я обращу в тщету все, что задумают Иудея и Иерусалим. Я повергну их мечом врага – падут они от руки тех, кто жаждет их смерти. Их трупы Я отдам на съедение птицам небесным и зверям земным.","8":"Я обреку этот город на ужас и унижение. Всякий, кто пройдет мимо, ужаснется, присвистнет, глядя на его руины.","9":"Я заставлю жителей этого города поедать плоть своих сыновей и дочерей. Каждый будет есть плоть своего соседа – во время осады и бедствий, на которые враги обрекут их, желая их смерти.","10":"Разбей кувшин на глазах у пришедших с тобою людей","11":"и скажи им: „Так говорит Господь Воинств: Я разобью этот народ и этот город! Так разбивают кувшин гончара, и невозможно собрать его снова. И для могил в Тофете уже не хватит места.","12":"Так Я поступлю с этим местом, – говорит Господь, – и с его жителями, сделаю этот город подобным Тофету!","13":"И будут осквернены дома Иерусалима, дома царей Иудеи, как Тофет, – все дома, где воскуряли на крышах воинству небесному и совершали возлияния богам иным\"».","14":"Иеремия вернулся из Тофета, куда Господь посылал его пророчествовать, встал во дворе Храма Господа и сказал всему народу:","15":"«Так говорит Господь Воинств, Бог Израиля: на этот город и на все подвластные ему города Я пошлю беды, которые Я предрек ему, ибо все они упрямы, слов Моих не слушают!»"},"20":{"1":"Священник Пашхур, сын Иммера, главный распорядитель в Храме Господа, услыхал пророчества Иеремии.","2":"Пашхур избил пророка Иеремию и посадил его в колодки, у Верхних Вениаминовых ворот при Храме Господа.","3":"На следующий день Пашхур освободил Иеремию из колодок. Иеремия сказал Пашхуру: «Господь дает тебе имя Кругом – Ужас, а не Пашхур.","4":"Ибо так говорит Господь: на ужас Я обрекаю тебя и всех, кто любит тебя. На твоих глазах они падут от меча врагов! Всех жителей Иудеи Я отдам в руки царя вавилонского: одних он угонит в Вавилон, других – убьет мечом!","5":"Все богатство этого города, все его достояние, все ценное в нем, все сокровища царей Иудеи – все отдам Я в руки врагов. Они все разграбят, захватят и унесут в Вавилон.","6":"И ты, Пашхур, и все твои домочадцы – вы отправитесь в плен. Ты придешь в Вавилон, и там умрешь, и там будешь похоронен – ты и все, кто любил тебя, кому ты ложно пророчествовал».","7":"Обманул Ты меня, Господь, и я обманут. Одолел Ты меня – ведь Ты сильнее. День – деньской надо мною смеются, все надо мной глумятся.","8":"Что ни слово мое – то стоны, я кричу: «Насилье, грабеж!» Слово Господа мне приносит униженье, насмешки с утра до ночи.","9":"И сказал я: «Напоминать о Нем не буду, говорить во имя Его – не стану!» Но вот, в моем сердце будто огонь пылает, в костях моих струится! Удержать его я тщился, но был не в силах.","10":"Слышу я злословье многих, кругом – угрозы! «Донесите! Давайте о нем объявим!» Те, с кем жил я в мире, ждут моего паденья: «Может, он впросак попадет, и тогда мы его одолеем, за все отплатим!»","11":"Но со мной Господь, словно воин могучий! Потому гонители дрогнут, бессильны будут, позором себя покроют, цели своей не достигнут. Позор их вовеки не забудется!","12":"Господь Воинств испытует справедливо, сердце Он видит и душу. Пусть увижу я, как Ты отомстишь им, ведь Тебе я тяжбу свою доверил!","13":"Пойте Господу, Господа славьте! Ибо Он бедняка спасает от руки злодеев.","14":"Проклят день, в который я родился! День, когда мать меня родила, – да не будет он благословен!","15":"Проклят тот, кто отцу принес известье: «Сын у тебя родился!» – и тем отца осчастливил.","16":"Человек тот пусть будет подобен городам, что Господь разрушил, не зная жалости. Пусть он стоны услышит утром, боевые кличи – в полдень!","17":"Ибо он не убил меня в утробе, чтобы стала мне мать могилой, а утроба ее – беременной вечно.","18":"Для чего из утробы я вышел – чтобы тяготы видеть и горе и дни окончить в позоре?"},"21":{"1":"Вот слово, которое было Иеремии от Господа, когда царь Седекия послал к Иеремии Пашхура, сына Малкии, и священника Софонию, сына Маасеи, с такими словами:","2":"«Проси Господа за нас, ибо Навуходоносор, царь Вавилона, ведет против нас войну! Быть может, Господь сотворит ради нас одно из Своих чудес и Навуходоносор от нас отступит».","3":"Иеремия ответил им: «Скажите Седекии:","4":"„Так говорит Господь, Бог Израиля: Я отниму у вас оружие, которым вы воюете с царем Вавилона и с халдеями, осадившими стены, Я соберу их внутри этого города!","5":"Я Сам буду сражаться против вас – рукой простертой, десницей могучей, в гневе и ярости, в негодовании великом!","6":"Я погублю всех живущих в этом городе, и людей и животных. От великого мора они погибнут!","7":"После этого, – говорит Господь, – Седекию, царя Иудеи, его слуг и весь народ, всех уцелевших в этом городе от мора, от меча и голода, Я отдам в руки Навуходоносора, царя вавилонского, в руки врагов, в руки тех, кто жаждет их смерти. Царь убьет их мечом, не пожалеет, не пощадит, не помилует!\"","8":"А народу скажи: „Так говорит Господь: Я даю вам путь жизни и путь смерти.","9":"Кто останется в городе, тот погибнет от меча, от голода и мора. Кто выйдет и сдастся халдеям, которые вас осадили, тот останется жив – жизнь и будет ему наградой.","10":"Ибо Я обратил Мой взор к этому городу на беду, не на благо, – говорит Господь. – Он будет отдан в руки царя вавилонского, и царь сожжет его огнем\"».","11":"Дом царя Иудеи! Слушай слово Господа,","12":"дом Давидов! Так говорит Господь: «С утра правый суд вершите, обездоленного избавьте от руки мучителя, чтобы ярость Моя не разгорелась, как пламя, как пожар, который никто не потушит, за все злодеяния ваши.","13":"Теперь Я иду против тебя, жительница долины, скала равнины! – говорит Господь. – Говорите вы: „Кто же до нас доберется, кто вторгнется в наши жилища?\"","14":"По плодам деяний ваших Я вас покараю! – говорит Господь. – Разожгу Я огонь в лесу вашем, и огонь все вокруг поглотит!»"},"22":{"1":"Так сказал Господь: «Иди во дворец царя Иудеи и возвести там такое слово.","2":"Скажи: слушай слово Господа, царь Иудеи, восседающий на престоле Давида, – ты, и твои слуги, и твой народ, все, кто входит через эти ворота!»","3":"Так говорит Господь: «Поступайте по справедливости и правде, обездоленного избавьте от руки мучителя! Чужеземца, сироту и вдову не обижайте, насилия над ними не совершайте и не проливайте на этом месте кровь невинную.","4":"Если вы исполните все это, то через ворота дворца будут в колесницах и верхом въезжать цари, восседающие на престоле Давида, – они, их слуги и народ.","5":"Если же не послушаетесь этих слов, тогда, клянусь Собою, – говорит Господь, – дворец этот станет грудой развалин».","6":"Ибо так говорит Господь о доме царя Иудеи: «Ты предо Мной – что Галаад, словно вершины Ливана. Но Я сделаю тебя пустыней, безлюдными городами!","7":"Я избрал против тебя губителей, каждому дал оружие. Твои лучшие кедры они срубят и в огонь их бросят.","8":"Многие народы будут проходить мимо этого города, и будут спрашивать друг друга люди: „За что Господь сделал с этим великим городом такое?\"","9":"И ответят: „За то, что они забыли договор с Господом, своим Богом, поклонялись богам иным и служили им\"».","10":"Не плачьте об умершем, головой не качайте! О том, кто ушел, рыдайте горько, ведь он уже не вернется, не увидит родную землю.","11":"Ибо так говорит Господь о царе Иудеи Шаллуме, сыне Иосии, который правил после своего отца Иосии и ушел отсюда: «Сюда он уже не вернется!","12":"В том месте, куда угнали его, он и умрет, а этой земли больше не увидит.","13":"Горе тому, кто дом свой строит несправедливостью, чертоги свои – беззаконием, ближнего заставляет работать даром, за труд ничего не платит!","14":"Говорит он: „Дом большой себе построю, просторные чертоги\". Делает себе он окна, обложенные кедром, разукрашенные алой краской.","15":"Неужели ты стал царем, чтобы кедром своим кичиться? Вот отец твой – и ел, и пил он, но поступал по справедливости и правде, потому и был благополучен.","16":"Разбирал он дело бедняка и нищего, потому и был благополучен. Это и значит – знать Меня! – говорит Господь. –","17":"У тебя же нет ни глаз, ни рассудка! Ты умеешь только искать наживу, лить кровь невинных, творить гнет и насилье».","18":"Потому так говорит Господь о царе Иудеи Иоакиме, сыне Иосии: «Не станут оплакивать его: „Горе! О брат мой! Горе! О сестра моя…\" Не станут оплакивать его: „Горе! О владыка! Горе! О слава его…\"","19":"Похоронят его, как осла хоронят, поволокут и выбросят из ворот Иерусалима.","20":"Иди, рыдай на Ливане, плач подними в Башане, рыдай на Авариме, ибо все любовники твои повержены!","21":"Я говорил с тобою, когда ты была счастливой, но сказала ты: „Не стану слушать!\" С юных лет ты так поступала, голоса Моего не слушалась!","22":"Пастырей твоих пасти будет ветер, любовников твоих в плен угонят. Опозорена ты будешь, унижена за все твои злодеянья!","23":"Обитательница Ливана, вьющая гнездо на кедрах! Застонешь ты, когда муки тебя охватят, словно боль при родах!","24":"Клянусь Собою! – говорит Господь. – Даже если бы перстнем с печатью на Моей деснице был царь Иудеи Иехония, сын Иоакима, то и тогда Я сорвал бы его!","25":"Я отдам тебя в руки тех, кто жаждет твоей смерти, в руки тех, перед кем ты трепещешь, – в руки Навуходоносора, царя вавилонского, в руки халдеев!","26":"Я изгоню тебя и твою мать, что тебя родила, в чужую страну – не там вы родились, но там умрете!","27":"А на эту землю, куда они всей душой хотят вернуться, они уже не вернутся».","28":"Разве этот человек, Иехония, – лишь горшок негодный, разбитый, сосуд ненужный? Почему же его увели вместе с потомками, угнали в страну, которой они не знают?","29":"О земля, земля, земля! Слушай слово Господа!","30":"Так говорит Господь: «Человека этого запишите бездетным, во все дни свои он будет несчастен! И никто из его потомков не будет счастлив, не воссядет на престоле Давида, чтобы властвовать над Иудеей»."},"23":{"1":"Горе пастухам, которые губят и рассеивают овец Моего стада! – говорит Господь.","2":"Так говорит Господь, Бог Израиля, пастухам, которые пасут Мой народ: «Вы рассеяли Моих овец, разогнали их, не заботились о них. Теперь Я покараю вас за ваши злодеяния! – говорит Господь. –","3":"И Я соберу остаток Моих овец из всех стран, куда Я изгнал их, и верну их в родную обитель, они будут плодиться и размножаться.","4":"Я поставлю над ними пастухов, которые будут пасти их. И не будут они больше бояться, не будут страшиться, не потеряются, – говорит Господь.","5":"Грядут дни, – говорит Господь, – когда Я возвышу потомка Давидова, Ветвь праведную! И воцарится царь, будет он мудр и будет вершить на земле справедливый суд.","6":"В дни его Иудея спасется, Израиль будет жить безмятежно. Вот имя, которым звать его будут: „Господь – оправдание наше\".","7":"Грядут дни, – говорит Господь, – когда не будут уже говорить: „Жив Господь, который вывел сынов Израиля из Египта!\" –","8":"будут говорить иначе: „Жив Господь, который вывел и привел потомков дома Израилева из земли северной\", – из всех стран, куда Я изгнал их! И будут они жить на своей земле».","9":"О пророках. Сокрушено мое сердце, дрожу я всем телом! Стал я словно пьяный, как человек, которого вино одолело, – пред лицом Господа, из-за слова Его святого!","10":"Земля полна прелюбодеев, из-за них земля рыдает – увяли пастбища степные. Цель их – злодейство, сила их – несправедлива,","11":"и пророк, и священник полны скверны. «Даже в Доме Моем злодеяния их вижу! – говорит Господь. –","12":"Потому их путь станет скользким, покроется тьмою. Их погонят – они будут падать. Ибо Я беду пошлю им в год кары! – говорит Господь. –","13":"Видел Я безумье пророков Самарии: именем Ваала они вещали, народ Мой, Израиль, с пути сбили.","14":"Вижу Я, и пророки Иерусалима творят ужасное: развратны они, живут неправдой, укрепляют руку злодеев, никто злых дел своих не оставляет. Для Меня они все – как Содом, жители столицы – как Гоморра!»","15":"Так говорит Господь Воинств о пророках: «Накормлю их полынью, напою водой ядовитой, ибо из-за пророков Иерусалима осквернена земля!»","16":"Так говорит Господь Воинств: «Не внимайте словам пророков, всему, что они вещают! Говорят они вам ложь пустую, виденья свои пересказывают, а не слова Господни.","17":"Твердят они без умолку тем, кто Меня презирает: „Господь сказал, что мир у вас будет!\" Тем, кто по упрямству сердца своего поступает, говорят они: „Не придут к вам беды!\"»","18":"Но кто стоял на совете Господнем, кто видел, кто слово Его слышал? Кто внимал Его слову и слышал?","19":"Вот ураган Господень поднялся в ярости! Ураган кружится, на головы злодеев он обрушится!","20":"Не утихнет гнев Господа, пока Он не свершит, не исполнит замысел Своего сердца. В дни грядущие вы это до конца поймете!","21":"«Не посылал Я пророков этих, сами они прибежали! Не говорил Я с ними, сами они вещают!","22":"Если бы на совете Моем они стояли, то Мои слова народу Моему возвестили бы, отвратили бы его от пути злого, от злодейства.","23":"Неужели Я лишь поблизости Бог? – говорит Господь. – Разве Я не Бог вдали?","24":"И в каком же месте сможет человек укрыться, чтобы Я его не видел? – говорит Господь. – Разве небо и земля не полны Мною? – говорит Господь.","25":"Я слышал, что говорят пророки, которые вещают от Моего имени ложь. Говорят они: „Видел, видел я сон!\"","26":"Доколе? Есть ли разум у этих пророков, которые вещают ложь, вещают вымыслы своего сердца?","27":"Думают они, что ради этих снов, которые они пересказывают друг другу, они заставят народ Мой позабыть Мое имя, как некогда отцы этого народа позабыли Мое имя ради Ваала.","28":"Пророк, который видел сон, пусть и рассказывает его как сон, а пророк, которому было Мое слово, пусть возвещает Мое слово истинное! Что общего у зерна и мякины? – говорит Господь. –","29":"Слово Мое – как пламя, – говорит Господь, – как молот, дробящий скалы!","30":"Иду Я против пророков! – говорит Господь. – Они слова Мои воруют друг у друга.","31":"Иду Я против пророков, – говорит Господь, – языками они болтают и рекут: „Вот Его речи!\"","32":"Иду Я против пророков, вещающих лживые сны! – говорит Господь. – Рассказывают они сны и дерзкой своей ложью вводят Мой народ в заблуждение. Я не посылал их, не давал им повелений, и никакой пользы не принесут они этому народу! – говорит Господь. –","33":"И когда спросит тебя этот народ, пророк или священник: „Какое пророчество послал Господь?\" – ответь им, что так говорит Господь: „Вы сами для себя пророчество, а Я вас оставил\".","34":"И если впредь пророк, священник или кто из народа произнесет слова „пророчество Господа\", Я покараю того человека и его дом.","35":"Говорите друг другу, брат брату: „Что ответил Господь? Что предрек Господь?\"","36":"О пророчестве же Господнем больше не вспоминайте, ибо для каждого из вас собственные слова стали пророчеством, а слова Бога Живого, Господа Воинств, слова Бога вашего, вы извратили.","37":"Говори пророку так: „Что ответил тебе Господь, что предрек Господь?\"","38":"Если же вы произнесете слова „пророчество Господа\", – так говорит Господь, – за то, что произнесли вы эти слова, „пророчество Господа\", хотя Я предупреждал вас – не говорите „пророчество Господа\", –","39":"за это Я вас забуду, отвергну вас и город этот, который Я дал вам и вашим отцам!","40":"Я обреку вас на вечный позор, на вечное унижение, которые не забудутся»."},"24":{"1":"Господь послал мне видение: вот две корзины со смоквами стоят перед Храмом Господним. (Было это после того, как Навуходоносор, царь Вавилона, увел из Иерусалима царя Иудеи Иехонию, сына Иоакима, вельмож Иудеи, ремесленников и кузнецов – угнал их всех в Вавилон.)","2":"И вот, в одной корзине – прекрасные, ранние смоквы, а в другой корзине – негодные смоквы, столь плохие, что их нельзя есть.","3":"Сказал мне Господь: «Что ты видишь, Иеремия?» Я ответил: «Смоквы. Вот хорошие смоквы – они прекрасны, вот плохие – они непригодны, столь плохи, что их нельзя есть».","4":"Было мне слово Господа.","5":"Так говорит Господь, Бог Израиля: «Благосклонно, как на эти хорошие смоквы, Я взгляну на изгнанников Иудеи, которых Я изгнал отсюда в халдейскую землю.","6":"На благо Я обращу к ним очи Мои и верну их на эту землю, укреплю их и не разрушу, насажу их и не вырву!","7":"Я дам им сердце разумное, чтобы они познали Меня, познали, что Я – Господь. Они будут Моим народом, Я буду их Богом, ибо вернутся они ко Мне всем своим сердцем.","8":"Словно с плохими смоквами, столь плохими, что их нельзя есть, – вот слова Господа, – так Я поступлю с Седекией, царем Иудеи, и его вельможами, со всеми оставшимися в Иерусалиме, в этой стране, и со всеми живущими в Египте.","9":"Для всех царств земли Я сделаю их примером ужаса и беды, обреку их на позор и поношение, издевательства и проклятия во всяком месте, куда изгоню их.","10":"Я буду посылать на них меч, голод и мор, пока все они не исчезнут с этой земли, которую Я дал им и отцам их»."},"25":{"1":"Вот слово, которое было Иеремии о всем народе Иудеи в четвертый год правления царя Иудеи Иоакима, сына Иосии (это был первый год правления Навуходоносора, царя вавилонского).","2":"Вот что возвестил пророк Иеремия всему народу Иудеи, всем жителям Иерусалима.","3":"Двадцать три года Господь возвещал мне Свое слово, с тринадцатого года правления царя Иудеи Иосии, сына Амона, и доныне. И я говорил вам, говорил снова и снова, но вы не слушали.","4":"Господь посылал к вам рабов Своих, пророков, посылал снова и снова, но вы не слушали, не внимали тому,","5":"что вам говорилось: «Пусть каждый из вас оставит злой путь свой, свои злодеяния! И живите на земле, которую Господь дал вам и отцам вашим на веки вечные!","6":"Не поклоняйтесь богам иным, не служите им, не простирайтесь ниц перед ними, не гневите Меня делами рук своих, и тогда Я не пошлю вам беду».","7":"«Но вы не слушали Меня! – говорит Господь. – Делами рук своих вы гневили Меня себе на горе».","8":"Потому так говорит Господь Воинств: за то, что вы не слушали Моих слов,","9":"Я созову и соберу все племена севера, – говорит Господь, – и призову раба Моего Навуходоносора, царя вавилонского, и поведу его против этой земли, ее жителей, против всех соседних народов. Я истреблю их, обреку их на ужас и унижение, на вечное опустошение!","10":"Я заставлю средь них умолкнуть голос радости и голос веселья, голос жениха и голос невесты, скрип ручных жерновов и огонь в светильнике.","11":"Вся земля эта станет пустыней и ужасом, в рабстве будут эти народы семьдесят лет у царя вавилонского.","12":"Когда минуют семьдесят лет, Я покараю царя вавилонского и его народ, – говорит Господь, – и землю халдеев за их преступления. Я сделаю ту землю пустыней навеки.","13":"Я совершу с той землею все, что Я предрек ей, что записано в этой книге, что предсказал Иеремия о народах.","14":"Ибо и они станут рабами у могучих народов, у царей великих – Я отплачу им по их поступкам, по их делам.","15":"Так сказал мне Господь, Бог Израиля: «Возьми из Моей руки эту чашу с вином ярости и напои им все народы, к которым Я тебя посылаю.","16":"Выпьют они, закачаются, обезумеют пред мечом, что Я на них посылаю».","17":"И взял я чашу из руки Господа и напоил все народы, к которым Господь послал меня:","18":"Иерусалим и города Иудеи, царей ее и вельмож – чтобы обречь их на опустошение и ужас, унижение и проклятие, которые обрушились на них ныне;","19":"фараона, царя египетского, его слуг и вельмож, весь его народ","20":"и всех иноплеменников среди них; всех царей земли Уц и всех царей земли филистимской – Ашкелон, Газу, Экрон и тех, кто уцелел в Ашдоде;","21":"Эдом, Моав и сынов Аммона;","22":"всех царей Тира и всех царей Сидона; царей в странах за морем;","23":"Дедан, Тему, Буз и всех, кто бреет себе виски;","24":"всех царей Аравии и всех царей, что правят племенами, живущими в пустыне;","25":"всех царей Зимри, всех царей Элама и всех царей Мидии;","26":"всех царей севера, близких и далеких, одного за другим, – все царства мира, какие есть на земле. А царь Шешаха будет пить последним.","27":"И скажи им: так говорит Господь Воинств, Бог Израиля: Пейте, пьянейте, блюйте, падайте, чтоб уже не подняться пред мечом, что Я на вас посылаю!","28":"И когда откажутся они испить чашу, которую ты дашь им своей рукою, скажи им: так говорит Господь Воинств: будете, будете пить!","29":"Если Я посылаю беды городу, который именем Моим осенен, неужели вы избежите кары? Не избежите вы кары, ибо Я призываю меч на всех жителей земли, – говорит Господь Воинств.","30":"Возвести им все эти слова и скажи им: С высоты Господь возгремит, из обители Своей святой возвысит голос, на овчарню Свою возгремит, закричит, как давильщик винограда, на всех жителей земли!","31":"До края земли гром раздается, ибо тяжба у Господа с народами, всех людей призывает Он к ответу, злодеев обрекает на меч, – говорит Господь.","32":"Так говорит Господь Воинств: вот идет беда от народа к народу, великая буря от края земли поднимается!","33":"В тот день убитые Господом будут лежать по всей земле, от края до края. Не оплачут их, не соберут, не похоронят, как навоз, на земле лежать они будут.","34":"Плачьте, пастухи, рыдайте, в пыли катайтесь, вожди стада, ибо ваши дни наступили – вас поведут на закланье! Будете вы рассеяны, разбиты, как сосуд драгоценный.","35":"Убежища пастухам не будет, не будет спасенья вождям стада.","36":"Плач пастухов раздается, рыданья вождей стада! Господь разорил их пастбище,","37":"овчарни мирные гибнут из-за яростного гнева Господнего.","38":"Он – словно лев, что из логова своего вышел! И земля их стала пустыней из-за гнева жестокого, из-за яростного Его гнева."},"26":{"1":"В начале правления царя Иудеи Иоакима, сына Иосии, от Господа было такое слово.","2":"Так говорит Господь: «Встань во дворе Храма Господа и возвести жителям городов Иудеи, пришедшим в Храм Господа совершить поклонение, все то, что Я повелел тебе сказать им, не пропусти ни слова!","3":"Быть может, они послушают и каждый из них оставит злой путь свой. И тогда Я передумаю, не пошлю им бедствие, которое Я хотел обрушить на них за их злодеяния.","4":"Скажи им: „Так говорит Господь: если вы не послушаетесь Меня, не будете жить по Закону Моему, который Я дал вам,","5":"не будете слушать речи рабов Моих, пророков, которых Я посылаю к вам, посылаю снова и снова, хоть вы и не слушаете их, –","6":"тогда Я сделаю с этим Храмом то, что сделал с Силомом, а город этот обреку на проклятья у всех народов земли\"».","7":"Иеремия возвестил все эти слова в Храме Господа, и священники, пророки и весь народ слушали его.","8":"Как только Иеремия сказал все то, что повелел ему Господь сказать народу, священники, пророки и народ схватили его и закричали: «Смерть тебе, смерть!","9":"Зачем ты, пророчествуя от имени Господа, говоришь, что с Храмом этим будет то же, что было с Силомом, что город этот будет разрушен, жителей в нем не останется?» Весь народ собрался в Храме Господа, чтобы судить Иеремию.","10":"Вельможи Иудеи, услыхав об этом, пришли из царского дворца к Храму Господа и сели там, у Новых ворот.","11":"И сказали священники и пророки вельможам и всему народу: «Этот человек заслуживает смерти! Вы сами слышали, что он пророчествовал об этом городе».","12":"Иеремия сказал вельможам и всему народу: «Господь послал меня возвестить об этом Храме и об этом городе пророчество, которое вы слышали.","13":"Сделайте добрыми ваши пути и деяния, повинуйтесь голосу Господа, Бога вашего, – и Господь передумает, не пошлет бедствие, которое Он предрек вам.","14":"А я – я в ваших руках, делайте со мной то, что кажется вам правильным и справедливым.","15":"Но знайте, если вы убьете меня, то кровью невинной запятнаете и себя, и этот город, и всех его жителей! Ибо, воистину, Господь послал меня к вам, чтобы я возвестил перед вами во всеуслышание все эти слова».","16":"Вельможи и весь народ сказали священникам и пророкам: «Этот человек не заслуживает смерти! От имени Господа, Бога нашего, говорил он с нами».","17":"Несколько старейшин страны поднялись и сказали всему народному собранию:","18":"«Во дни Езекии, царя Иудеи, пророчествовал Михей из Морешета. Возвестил он всему народу Иудеи: Так говорит Господь Воинств: распашут Сион, как поле, грудой камней Иерусалим станет, а гора, на которой этот Храм построен, – холмом лесистым!","19":"Но разве царь Езекия и вся Иудея осмелились убить пророка? Разве царь не испугался Господа, не постарался умилостивить Его? И Господь передумал, не послал бедствие, которое Он предрек им. А мы творим великое зло самим себе!»","20":"(Был и другой человек, который пророчествовал от имени Господа, – Урия, сын Шемай, из Кирьят – Иеарима. Он пророчествовал об этом городе и об этой земле то же самое, что и Иеремия.","21":"Когда царь Иоаким со всеми своими воинами и вельможами услыхал слова пророка, то захотел убить его. Урия узнал об этом, испугался и бежал в Египет.","22":"Царь Иоаким послал своих людей в Египет – послал туда Элнатана, сына Ахбора, и людей с ним.","23":"Они увели Урию из Египта и привели его к царю Иоакиму. Царь убил Урию мечом, а труп велел бросить в могилу для простолюдинов.)","24":"Итак, только благодаря Ахикаму, сыну Шафана, Иеремию не выдали народу на смерть."},"27":{"1":"В начале правления царя Иудеи Седекии, сына Иосии, было Иеремии слово от Господа.","2":"Так сказал мне Господь: «Сделай ярмо и путы и надень их себе на шею.","3":"И отошли их царю Эдома, царю Моава и царю сынов Аммона, царю Тира и царю Сидона – через послов, которые пришли в Иерусалим к Седекии, царю Иудеи.","4":"Вели послам, чтобы они сказали своим владыкам: Так говорит Господь Воинств, Бог Израиля: скажите своим владыкам:","5":"Я сотворил землю, человека и зверя, что на земле обитают, силой Моей великой, рукой простертой! Я тому отдам эту землю, кто Мне угоден.","6":"Ныне Я отдаю все эти земли в руки раба Моего Навуходоносора, царя вавилонского, – даже диких зверей отдаю ему в рабство.","7":"Служить ему будут все народы, и сыну его, и внуку, пока и его земле не придет черед – и тогда его покорят многочисленные народы, цари великие.","8":"Но если теперь какой народ или царство не станет служить ему, Навуходоносору, царю Вавилона, не подставит шею под ярмо царя вавилонского, то Я покараю такой народ мечом, голодом и мором, – говорит Господь, – полностью истреблю его рукой царя.","9":"Не слушайте ваших пророков, гадателей, сновидцев, предсказателей и чародеев, которые говорят вам: „Вы не будете рабами царя вавилонского!\"","10":"Ибо ложь они вам вещают, чтобы вы оказались вдали от своей земли, чтобы Я изгнал вас и вы погибли.","11":"А тот народ, что подставит шею под ярмо царя вавилонского и будет служить ему, – Я оставлю тот народ на его земле, – говорит Господь, – будет он возделывать ее и жить на ней».","12":"Все эти слова я возвестил Седекии, царю Иудеи: «Согните шею под ярмом царя вавилонского! Служите ему и его народу – и живите!","13":"Зачем тебе и народу твоему погибать от меча, от голода и мора? Ведь Господь предрек это всякому народу, который не станет служить царю Вавилона.","14":"Не слушайте пророков, которые говорят вам: „Вы не будете рабами царя вавилонского!\" – ибо ложь они вам вещают.","15":"„Я не посылал их, – говорит Господь. – От Моего имени они пророчествуют ложно, чтобы Я изгнал вас. Погибнете вы, а с вами и пророки, которые вам вещают!\"»","16":"Священникам и всему народу я возвестил: «Так говорит Господь: не слушайте ваших пророков, которые вам предсказывают: „Уже скоро утварь дома Господнего будет возвращена из Вавилона!\" – ибо ложь они вам вещают.","17":"Не слушайте их, служите царю Вавилона – и живите! Зачем этому городу превращаться в руины?","18":"Если они пророки, если слово Господа с ними, то пусть они молят Господа Воинств, чтобы та утварь, которая еще остается в Храме Господа, во дворце царя Иудеи и в Иерусалиме, не была увезена в Вавилон.","19":"Ибо так говорит Господь Воинств о столбах, о медном море, подставках и прочей утвари, которая еще остается в этом городе,","20":"которую Навуходоносор, царь Вавилона, не забрал с собою, когда угнал из Иерусалима в Вавилон царя Иудеи Иехонию, сына Иоакима, и всю знать Иудеи и Иерусалима, –","21":"так говорит Господь Воинств, Бог Израиля, об утвари, которая еще остается в Храме Господа, во дворце царя Иудеи и в Иерусалиме:","22":"„Увезут ее в Вавилон, и там она останется, пока Я не позабочусь о ней, – говорит Господь, – пока не заберу ее и не возвращу на это место\"»."},"28":{"1":"В четвертый год правления Седекии, царя Иудеи, в пятом месяце, Ханания, сын Аззура, пророк из Гаваона, сказал мне в Храме Господа на глазах у священников и всего народа:","2":"«Так говорит Господь Воинств, Бог Израиля: Я разобью ярмо царя вавилонского!","3":"Через два года Я возвращу на это место всю утварь Храма Господнего, которую Навуходоносор, царь Вавилона, забрал отсюда и увез в Вавилон.","4":"Царя Иудеи Иехонию, сына Иоакима, и всех, кто был угнан из Иудеи в Вавилон, Я возвращу на это место, – говорит Господь, – ибо Я разобью ярмо царя вавилонского».","5":"Пророк Иеремия ответил пророку Ханании на глазах у священников и всего народа, стоящего в Храме Господа, –","6":"сказал пророк Иеремия: «Пусть Господь сделает именно так, пусть Он исполнит твое пророчество, вернет сюда из Вавилона утварь Дома Господнего и всех изгнанников!","7":"Но послушай, что я скажу тебе и всему народу во всеуслышание.","8":"Пророки, что были в древности, прежде меня и прежде тебя, предсказывали многим странам, великим царствам войны, беды и мор.","9":"Если же пророк предсказывает мир, то лишь тогда узнают, что он действительно пророк, посланный Господом, когда сбудутся слова этого пророка».","10":"Пророк Ханания сорвал ярмо с шеи пророка Иеремии и разбил его.","11":"И сказал Ханания перед всем народом: «Так говорит Господь: вот так через два года Я разобью ярмо, что на шее у всех народов, ярмо Навуходоносора, царя вавилонского!» Пророк Иеремия пошел своей дорогой.","12":"После того как пророк Ханания разбил ярмо, что было на шее у пророка Иеремии, было Иеремии слово Господа:","13":"«Иди и скажи Ханании: „Так говорит Господь: ты разбил ярмо деревянное, но вместо него Я сделаю ярмо железное!","14":"Ибо так говорит Господь Воинств, Бог Израиля: ярмо железное Я надену на шею всем этим народам, чтобы стали они рабами Навуходоносора, царя вавилонского! Будут они его рабами, и даже диких зверей Я отдам ему\"».","15":"И пророк Иеремия сказал пророку Ханании: «Слушай, Ханания! Не посылал тебя Господь! Ты внушил этому народу ложные надежды.","16":"Потому так говорит Господь: Я смету тебя с лица земли – в этом году ты умрешь, ибо ты лгал от имени Господа».","17":"В том же году, в седьмом месяце, пророк Ханания умер."},"29":{"1":"Вот письмо, которое пророк Иеремия отправил из Иерусалима тем старейшинам, что были среди пленников, а также священникам, пророкам и всему народу, угнанному Навуходоносором из Иерусалима в Вавилон.","2":"После того как царь Иехония и его мать, евнухи, вельможи Иудеи и Иерусалима, ремесленники и кузнецы были уведены из Иерусалима,","3":"отправлено было это письмо – через Эласу, сына Шафана, и Гемарию, сына Хилкии, которых Седекия, царь Иудеи, послал в Вавилон, к Навуходоносору, царю вавилонскому.","4":"«Так говорит Господь Воинств, Бог Израиля: Всем изгнанникам, которых изгнал Я из Иерусалима в Вавилон!","5":"Дома себе стройте и в них живите, сады разводите и плоды их ешьте.","6":"Жен себе возьмите, сыновей и дочерей рожайте, сыновей своих жените, дочерей выдавайте замуж, чтобы и они детей рожали. Размножайтесь там, да не станет вас меньше!","7":"Желайте мира тому городу, куда Я изгнал вас, молите Господа о том городе, ибо если в нем будет мир, то мир будет и у вас.","8":"Так говорит Господь Воинств, Бог Израиля: пусть не обманут вас пророки и гадатели, которые среди вас, не слушайте сновидцев с их снами!","9":"Эти люди вещают вам от Моего имени ложь, Я не посылал их, – говорит Господь.","10":"Так говорит Господь: когда минуют семьдесят лет, отпущенные Вавилону, Я позабочусь о вас, исполню ради вас слово Мое благое – верну вас на это место!","11":"Ибо только Я знаю, что Я предначертал вам, – говорит Господь. – Предначертал Я мир, а не беду, чтобы дать вам будущее и надежду.","12":"Вы призовете Меня, пойдете и будете Мне молиться, и Я вас услышу.","13":"Будете искать Меня и найдете, ведь вы всем сердцем будете стремиться ко Мне.","14":"Я явлюсь вам, – говорит Господь, – Я верну вас из плена, соберу вас от всех народов, из всех мест, куда Я изгнал вас, – говорит Господь, – и верну вас туда, откуда Я изгнал вас.","15":"Вы говорили: „Господь дал нам пророков и в Вавилоне!\"","16":"Так говорит Господь о царе, который восседает на престоле Давида, и обо всем народе, который живет в этом городе, о ваших братьях, что не уведены с вами в изгнание, –","17":"так говорит Господь Воинств: Я посылаю на них меч, голод и мор! Я поступлю с ними как с гнилыми смоквами, которые столь плохи, что их нельзя есть.","18":"Я буду преследовать их мечом, голодом и мором. Я сделаю их примером страшным для всех царств земли, обреку их на проклятие и ужас, на унижение и позор среди всех народов, куда бы Я ни изгнал их.","19":"Ибо не слушали они Моих слов, – говорит Господь, – которые Я посылал им через рабов Моих, пророков, посылал снова и снова, но они не слушали, – говорит Господь. –","20":"А вы, изгнанники, которых отправил Я из Иерусалима в Вавилон, слушайте слово Господа!","21":"Так говорит Господь Воинств, Бог Израиля, об Ахаве, сыне Колаи, и Седекии, сыне Маасеи, которые вещают вам ложь от Моего имени: Я отдам их в руки Навуходоносора, царя вавилонского, и он убьет их у вас на глазах!","22":"В память о них появится среди иудеев – изгнанников в Вавилоне такое проклятье: „Пусть Господь сделает с тобою то же, что с Седекией и Ахавом, которых царь Вавилона изжарил на огне!\"","23":"Ибо творили они гнусности в Израиле – прелюбодействовали с чужими женами, говорили от Моего имени ложь, то, что Я не повелевал им. Я знаю это, Я тому свидетель! – говорит Господь».","24":"Скажи Шемае из Нехелама:","25":"«Так говорит Господь Воинств, Бог Израиля: самовольно ты послал письмо всему народу Иерусалима, священнику Софонии, сыну Маасеи, и всем остальным священникам! В этом письме говорилось:","26":"„Господь поставил тебя, Софония, священником вместо священника Иехояды, чтобы ты надзирал в Храме Господа за одержимыми, которые берутся пророчествовать, чтобы ты надевал на них колодки и оковы.","27":"Почему же ты не остановишь Иеремию из Анатота, который у вас пророчествует?","28":"Ведь он отправил к нам в Вавилон такое послание: Долгим будет изгнанье! Дома себе стройте и в них живите, сады разводите и плоды их ешьте\".","29":"Священник Софония прочитал это письмо пророку Иеремии.","30":"И было Иеремии слово Господа:","31":"отправь послание всем изгнанникам: так говорит Господь о Шемае из Нехелама: за то, что пророчествовал вам Шемая, хотя Я не посылал его, и внушил вам ложные надежды, за это, –","32":"так говорит Господь, – Я покараю Шемаю из Нехелама и его потомков! Никто из его потомков не будет жить среди этого народа, не увидит блага, которое Я совершу для Моего народа, – говорит Господь, – ибо Шемая лгал от имени Господа»."},"30":{"1":"Вот слово, которое было Иеремии от Господа.","2":"«Так говорит Господь, Бог Израиля: всё, что Я говорил тебе, запиши в свиток.","3":"Ибо настанут дни, – говорит Господь, – когда Я верну из плена народ Мой, Израиль и Иуду, – говорит Господь, – верну их на землю, которую Я дал их отцам, чтобы они владели ею».","4":"Вот слова, которые сказал Господь об Израиле и об Иуде.","5":"Так говорит Господь: крики ужаса мы слышим, страх и смятенье повсюду!","6":"Расспросите, смотрите! Разве может родить мужчина? Что же Я вижу: мужчины корчатся, словно роженицы! Исказились их лица смертельной бледностью.","7":"Горе! Ибо день тот велик, не было ему подобного. Это время беды для Иакова, но он спасется!","8":"В тот день, – говорит Господь Воинств, – Я разобью ярмо, что у тебя на шее, разорву оковы! Тогда не будут больше служить чужеземцам,","9":"служить будут Господу, своему Богу, и царю своему – Давиду, которого Я поставлю над ними.","10":"А ты, раб Мой Иаков, не бойся, – говорит Господь, – не страшись, Израиль! Я спасу тебя, верну из страны далекой, потомков твоих – из страны плена. Вернется Иаков, будет жить безмятежно и мирно, и врагов у него не будет.","11":"Ибо Я с тобою, – говорит Господь, – Я спасу тебя! Я уничтожу все народы, средь которых тебя рассеял. Лишь тебя Я не уничтожу, но покараю тебя по заслугам, без наказанья тебя не оставлю!","12":"Так говорит Господь: раны твои ужасны, тяжелы твои увечья!","13":"Дела твоего никто не разбирает, для язв твоих нет лекарства, нет тебе исцеленья.","14":"Все любовники твои тебя забыли, к тебе не стремятся. Удары врагов Я на тебя обрушил, жестокую кару, ибо велико твое преступленье, грехи твои бессчетны.","15":"Что о ранах своих ты стонешь, об увечьях тяжких? Велико твое преступленье, грехи твои бессчетны, потому Я так поступил с тобою.","16":"Но все, кто тебя пожирал, пожраны будут, кто тебя притеснял, уйдет в изгнанье! Те, кто грабил тебя, будут ограблены, кто брал у тебя добычу – их самих Я сделаю добычей!","17":"Я дам тебе исцеленье, от ран тебя вылечу, – говорит Господь. – Называли тебя отвергнутой: «Вот она, столица на Сионе, никому она не нужна!»","18":"Так говорит Господь: Я вновь поставлю шатры Иакова, над его жилищами смилуюсь! На руинах поднимется город, на прежнем месте дворец встанет.","19":"Вознесут они хвалебные молитвы, возликуют шумно! Я умножу их, впредь не станет их меньше, возвеличу их – не будут они унижены.","20":"Сыновья их будут как прежде, община их предо Мной укрепится, притеснителей их покараю!","21":"Вождь их – из их числа будет, их владыка – из их среды выйдет. Я приближу его, ко Мне он будет близок. Ведь кто посмеет приблизиться ко Мне самовольно? – говорит Господь. –","22":"И будете вы Моим народом, Я буду вашим Богом!","23":"Вот ураган Господень поднялся в ярости! Ураган несется, на головы злодеев он обрушится!","24":"Не утихнет яростный гнев Господа, пока Он не свершит, не исполнит замысел Своего сердца. В дни грядущие вы это поймете."},"31":{"1":"В то время, – говорит Господь, – Я буду Богом для каждого рода в Израиле, они будут Моим народом.","2":"Так говорит Господь: в пустыне нашел прощенье народ, от меча уцелевший. Израиль получит отдых!","3":"Вдали Господь мне явился: Я люблю тебя вечной любовью, творю тебе милость!","4":"Укреплю тебя снова, и ты будешь крепкой, о дева Израиля! Снова возьмешь свой бубен, выйдешь в радостном танце,","5":"снова лозу посадишь на горах Самарии. Виноградари посадят виноградник и плоды его отведают сами!","6":"Ибо день назначен, когда закричат дозорные на горах Ефрема: «Вставайте, взойдем на Сион, к Господу, нашему Богу!»","7":"Ибо так говорит Господь: Иакову радостно пойте, главу народов славьте! Провозглашайте и восхваляйте, говорите так: «Спаси, о Господь, народ Твой, остаток Израиля!»","8":"Я приведу их из страны северной, от краев земли соберу их. Среди них – слепые и хромые, беременные и роженицы, великой толпой они вернутся.","9":"Уходили они со слезами – теперь Я поведу их, утешив, поведу их к потокам водным по прямой дороге, на ней они не споткнутся. Ибо стал Я отцом Израилю, Ефрем – Мой первенец!","10":"Слушайте слово Господа, народы! На далеких берегах возвестите, говорите так: «Тот, кто рассеял Израиль, Тот его соберет, будет беречь его, как пастух – свое стадо».","11":"Господь выкупил Иакова, от руки необоримой избавил!","12":"Придут они, на горе Сион возликуют, возрадуются Господним щедротам – пшенице, молодому вину и маслу, коровам и овцам. Станет душа их как сад цветущий, страданье их завершится.","13":"Будут радоваться в хороводе девы, и юноши, и старцы! Скорбь Я сменю весельем, Я их утешу, после печалей пошлю им радость.","14":"Напитаю священников едою лучшей, и народ Мой щедротами Моими насытится, – говорит Господь.","15":"Так говорит Господь: плач в Раме раздается, горькие рыданья! То Рахиль о детях своих рыдает, и не может она утешиться, ибо детей ее нет больше.","16":"Так говорит Господь: сдержи рыданья, из очей твоих пусть не льются слезы, ибо за труд твой будет награда, – говорит Господь, – они из страны врагов вернутся!","17":"Надежда твоя – в будущем, – говорит Господь, – сыновья в удел свой вернутся!","18":"Слышу Я, как Ефрем стонет: «Наказал Ты меня – я наказан, словно телец упрямый! Верни меня, чтобы я вернулся, ибо Ты – Господь, Бог мой!","19":"Я свернул с пути, но после раскаялся, я был уличен – по бедру себя ударил! Посрамлен я, унижен, несу позор своей юности».","20":"Но разве Ефрем – не сын Мой милый, не дитя Мое дорогое? Я не раз обрекал его на беды, но помню, помню Я о Ефреме! Сердце Мое о нем тоскует, его Я помилую! – говорит Господь.","21":"Поставь себе путевые камни, установи вехи, обрати свое сердце на путь прямой, по которому шла ты прежде! Вернись, о дева Израилева, вернись в города свои!","22":"Доколе будешь метаться, о дочь – отступница?! Господь сотворил то, чего на земле не бывало: жена вновь возле Мужа.","23":"Так говорит Господь Воинств, Бог Израиля: «Когда Я верну их из плена, вновь будут говорить на земле Иудеи и в ее городах такие слова: „Обитель праведности, гора святая! Да благословит тебя Господь!\"","24":"И будет жить на этой земле Иуда, все его города, земледельцы и пастухи, что ходят со стадами.","25":"Уставшим Я дам напиться, истомленным Я дам насытиться».","26":"Тут я проснулся, открыл глаза. Сладок был мой сон.","27":"«Настанут дни, – говорит Господь, – когда Я наполню Израиль и Иудею людьми и скотом.","28":"Раньше Я не спускал с них глаз, чтобы искоренять и разрушать, сокрушать и губить, творить им зло. Так и теперь Я не спущу с них глаз, чтобы строить и насаждать, – говорит Господь. –","29":"В те дни уже не будут говорить: „Отцы виноград незрелый ели, а у детей испортились зубы\".","30":"Ибо человека будут карать смертью только за его преступления: кто съест виноград незрелый – у того и испортятся зубы.","31":"Настанут дни, – говорит Господь, – когда Я заключу с потомками Израиля и с потомками Иуды Договор Новый –","32":"не такой договор, какой Я заключил с их отцами, когда взял их за руку и вывел их из Египта. Тот договор они нарушили, хотя Я был их Владыкой, – говорит Господь. –","33":"Иной договор Я заключу тогда с потомками Израиля, – говорит Господь. Я вложу Закон Мой им в сердце, в их сердцах его начертаю. Я буду их Богом, они будут Моим народом!","34":"И никто больше не будет наставлять ближнего своего, брата своего, говоря: „Познайте Господа!\" – ибо все они, от мала до велика, будут знать Меня, – говорит Господь. – Я прощу им преступление их, о грехе их больше не вспомню.","35":"Так говорит Господь, который даровал солнце, чтобы днем оно сияло, законы даровал луне и звездам, чтобы ночью они светили, который волнует море, и волны морские рокочут, Тот, чье имя – Господь Воинств:","36":"как законы эти незыблемы предо Мной, – говорит Господь, – так потомки Израиля предо Мной останутся народом вечным.","37":"Так говорит Господь: как высокое небо не измерить, не отыскать оснований земли глубоких, так и Я не отвергну потомков Израиля за их поступки! – говорит Господь.","38":"Настанут дни, – говорит Господь, – когда город этот будет отстроен во славу Господа от башни Хананэла до Угловых ворот.","39":"Мерный шнур протянется до холма Гарев, а оттуда повернет к Гоа .","40":"Вся долина, что ныне полна мертвых тел и пепла, все поля до потока Кедрон, до Конских ворот на востоке – все это станет святыней Господней, которая уже никогда не будет разрушена, не будет уничтожена»."},"32":{"1":"Вот слово, которое было Иеремии от Господа в десятый год правления Седекии, царя Иудеи (это был восемнадцатый год правления Навуходоносора).","2":"Тогда войско царя вавилонского осаждало Иерусалим, а пророк Иеремия был заключен на дворе стражи при дворце царя Иудеи.","3":"Седекия, царь Иудеи, заключил туда Иеремию, сказав ему: «Зачем ты так пророчествуешь? Ты говоришь: „Так говорит Господь: Я отдам этот город в руки царя вавилонского, царь захватит город!","4":"Не спасется от рук халдеев и Седекия, царь Иудеи, попадет он в руки царя вавилонского, будет говорить с ним лицом к лицу, глаза в глаза.","5":"Царь уведет Седекию в Вавилон, и останется там Седекия, пока Я не позабочусь о нем, – говорит Господь. – Ибо вы сразитесь с халдеями, но не победите\"».","6":"Иеремия ответил: «Было мне слово Господа:","7":"придет к тебе Ханамэл, сын твоего дяди Шаллума, и скажет: „Купи мое поле возле Анатота, ведь ты обязан выкупить его и приобрести\"».","8":"И вот, как и сказал Господь, пришел ко мне на двор стражи Ханамэл, сын моего дяди, и сказал: «Купи мое поле возле Анатота, в земле Вениаминовой, ведь ты обязан владеть им, ты должен его выкупить. Купи же его!» И понял я, что это воля Господа.","9":"Я купил у Ханамэла, сына моего дяди, поле возле Анатота. Я отвесил Ханамэлу серебро – семнадцать шекелей серебра.","10":"Я сделал запись в купчей, поставил печать, призвал свидетелей и отвесил серебро на весах.","11":"Я взял эту купчую (запечатанную запись и незапечатанную)","12":"и передал ее Баруху, сыну Нерии, сына Махсеи, на глазах у Ханамэла, сына моего дяди, на глазах у свидетелей, сделавших запись в купчей, на глазах у всех иудеев, находившихся на дворе стражи.","13":"У них на глазах я дал руху такое повеление:","14":"«Так говорит Господь Воинств, Бог Израиля: возьмите эту купчую, запечатанную запись и незапечатанную, и положите в глиняный сосуд, чтобы хранилась она долгое время.","15":"Ибо так говорит Господь Воинств, Бог Израиля: еще будут на этой земле покупать дома, поля и виноградники!»","16":"Я отдал купчую Баруху, сыну Нерии, и стал молиться Господу:","17":"О Господи, Боже! Ты создал небо и землю силой Своей великой, рукой простертой, все для Тебя возможно!","18":"Тысячам людей творишь Ты милость, за грех отцов караешь потомков. О Бог великий и могучий! Его имя – Господь Воинств.","19":"Велик Его замысел, деянья – бесчисленны. Глаза Твои видят все пути людские, и каждому Ты воздаешь за его путь, по плодам дел его.","20":"Ты явил знамения и чудеса в Египте и являешь их до сих пор, и в Израиле, и среди всех людей, – Ты сотворил Себе имя, которое у Тебя ныне!","21":"Ты вывел народ Свой, Израиль, из Египта знамениями и чудесами, рукой могучей, десницей простертой, великим ужасом.","22":"Ты дал им эту землю, о которой клялся их отцам, обещая даровать ее – землю, текущую молоком и медом.","23":"И пришли они, завладели ею. Но голосу Твоему они не повиновались, по Закону Твоему не жили. То, что Ты заповедал им делать, они не делали – и Ты послал им все эти беды!","24":"Вот, осадные насыпи достигли города, и будет он захвачен, будет отдан этот город в руки халдеев, которые его осадили, падет он от меча, от голода и мора. То, что Ты предрек, свершилось, и теперь Ты смотришь на это.","25":"И Ты, Господи, Боже, велишь мне: «Купи себе поле за серебро, призови свидетелей». Но ведь этот город будет отдан в руки халдеев!","26":"И было Иеремии слово Господа:","27":"Я, Господь, – Бог всего живого! Разве есть невозможное для Меня?","28":"Так говорит Господь: Я отдам этот город в руки халдеев, в руки Навуходоносора, царя вавилонского, царь захватит город!","29":"Халдеи, что осаждают город, войдут в него и предадут его огню – сожгут город, сожгут дома, где на крышах воскуряли Ваалу и совершали возлияния богам иным, Меня гневили.","30":"Ибо сыны Израиля и сыны Иуды с юных лет творили лишь то, что Мне ненавистно, лишь гневили Меня сыны Израиля делами своими, – говорит Господь. –","31":"Этот город вызывал Мою ярость и гнев со дня основания своего и доныне. Потому Я отвергну его –","32":"за все зло, которое совершали сыны Израиля и сыны Иуды, вызывая Мой гнев, – сами они и цари их, их вельможи, священники и пророки, люди Иудеи, жители Иерусалима.","33":"Не лицом ко Мне они повернулись, а спиною. Я учил их, учил снова и снова, но они не слушали, не принимали наставления.","34":"Мерзости свои они поставили в Храме, который именем Моим осенен, и Храм этот осквернили.","35":"Построили они капища Ваалу в долине Бен – Хинном, чтобы отдавать Молоху своих сыновей и дочерей. Я не заповедовал им этого – сердцу Моему не угодно, чтобы творилась эта мерзость! Из-за нее погрязла в грехе Иудея.","36":"Но так говорит Господь, Бог Израиля, об этом городе, о котором вы говорите, что отдан он в руки царя вавилонского, обречен на меч, голод и мор:","37":"Я соберу их из всех стран, куда Я изгнал их в гневе и ярости, в негодовании великом, и верну их на это место, и дам им жизнь безмятежную.","38":"Они будут Моим народом, Я буду их Богом.","39":"Я дам им сердце единое и путь единый, чтобы во все дни они боялись Меня на благо себе и своим потомкам.","40":"Я заключу с ними вечный договор, не отвернусь от них, не перестану творить им благо. Я вложу в их сердца страх предо Мною, чтобы они от Меня не отступили.","41":"Всем сердцем Моим, всей Моей душою Я буду радоваться им, буду творить им благо, воистину насажу их на этой земле.","42":"Ибо так говорит Господь: Я послал этому народу великое зло, но Я пошлю им и благо, которое Я предрекаю им ныне.","43":"И будут покупать поля на этой земле, о которой вы говорите, что она – пустыня, что нет на ней ни человека, ни зверя, что отдана она в руки халдеев.","44":"Здесь будут покупать поля за серебро, будут делать запись в свитке, ставить печать, призывать свидетелей – и в земле Вениаминовой, и вокруг Иерусалима, во всех городах Иудеи: и в городах гор, и в городах Шефелы, и в городах Негева, ибо Я верну их из плена! – говорит Господь."},"33":{"1":"И было Иеремии слово Господа (второе за то время, пока он был заключен на дворе стражи).","2":"Так говорит Господь, Господь, создавший землю, Тот, кто облик ей дал, ее упрочил, Тот, чье имя – Господь:","3":"призови Меня, и Я отвечу, возвещу тебе о великом и недоступном, о том, чего ты не знаешь.","4":"Так говорит Господь, Бог Израиля, о домах этого города и о царских дворцах Иудеи, которые рухнут пред мечом осаждающих:","5":"жители их идут сразиться с халдеями, но дома эти наполнятся трупами! Буду Я губить жителей в гневе Моем и ярости! Ибо Я скрыл Мой лик от этого города за все их злодейства.","6":"Но Я дарую городу излечение и исцеление, Я исцелю их, Я открою им путь мира и правды.","7":"Я верну из плена Иуду, верну Израиль, укреплю их, как прежде.","8":"Я очищу их от преступлений – против Меня они грешили. Я прощу им все преступленья – против Меня они грешили, против Меня восставали.","9":"Станет для Меня этот город радостным именем, хвалой и славой у всех народов земли. Услышат они о благе, которое Я даровал этому городу, затрепещут они, задрожат – узнав о благе и мире, что Я даровал этому городу.","10":"Так говорит Господь: об этом месте вы говорите: «Это – пустыня, нет здесь ни человека, ни зверя!» Но в городах Иудеи, которые ныне опустошены, на улицах Иерусалима, где ныне не осталось ни единого жителя, ни людей, ни животных, – здесь вновь будет раздаваться","11":"голос радости и голос веселья, голос жениха и голос невесты! Здесь будут раздаваться возгласы людей, приносящих благодарственные жертвы в Храме Господа: «Благодарите Господа Воинств, ибо благ Господь, ибо милость Его – вовеки!» Я переменю участь этой земли, и все будет как прежде, – говорит Господь.","12":"Так говорит Господь Воинств: на этом опустевшем месте, где не осталось ни человека, ни зверя, возле всех этих городов еще будут пастбища, на которых пастухи дадут отдых своим стадам.","13":"Возле городов в горах и возле городов Шефелы, возле городов Негева и в земле Вениаминовой, в окрестностях Иерусалима – возле всех городов Иудеи вновь будут пастись стада – под властью того, кто будет о них заботиться, – говорит Господь.","14":"Настанут дни, – говорит Господь, – когда Я исполню благое слово, которое Я возвещал дому Израиля и дому Иуды.","15":"В те дни, в то время по воле Моей произрастет праведная Ветвь, потомок Давида, и будет он вершить на земле справедливый суд.","16":"В те дни Иудея спасется, Иерусалим будет жить безмятежно. И зваться он будет так: «Господь – оправдание наше».","17":"Ибо так говорит Господь: род Давида не пресечется на престоле Израиля.","18":"И всегда будут священники – левиты совершать предо Мной всесожжения, сжигать хлебные приношения и совершать ежедневные жертвы.","19":"И было Иеремии слово Господа.","20":"Так говорит Господь: как не в силах вы расторгнуть договор Мой с днем, договор Мой с ночью, и в свой черед день и ночь наступают,","21":"так не будет расторгнут Мой договор с рабом Моим Давидом, и потомки его будут править на его престоле. Так не будет расторгнут мой договор со священниками – левитами, Моими слугами.","22":"Небесное воинство не исчислить, песок морской не измерить – так Я умножу потомков раба Моего Давида и слуг Моих – левитов.","23":"И было Иеремии слово Господа:","24":"разве ты не видишь? Эти люди говорят: «Отверг Господь два племени, которые избрал раньше!» Презирают Мой народ, больше не считают его народом.","25":"Так говорит Господь: как заключил Я договор с днем и с ночью, утвердил законы неба и земли,","26":"так не отвергну Я потомков Иакова, потомков раба Моего Давида: из них буду выбирать владыку над потомками Авраама, Исаака, Иакова! Я верну их из плена, помилую."},"34":{"1":"Вот слово, которое было Иеремии от Господа, когда Навуходоносор, царь Вавилона, и все его войско, все царства и народы подвластной ему земли осаждали Иерусалим и окрестные города.","2":"Так говорит Господь, Бог Израиля: иди и скажи Седекии, царю Иудеи, скажи ему: «Так говорит Господь: Я отдаю этот город в руки царя вавилонского, и царь сожжет его огнем.","3":"И ты сам от руки царя не спасешься, будешь ты схвачен, попадешь к нему в руки. Ты предстанешь перед царем вавилонским, будет он говорить с тобою лицом к лицу, и пойдешь ты в Вавилон.","4":"Но послушай слово Господа, Седекия, царь Иудеи! Так говорит тебе Господь: от меча ты не погибнешь,","5":"умрешь мирно. Как сжигали благовония на похоронах отцов твоих, древних царей, живших прежде тебя, так и на твоих похоронах сожгут благовония и пропоют плач „Горе! О владыка…\"Ибо Я предрек это, – говорит Господь».","6":"Все эти слова пророк Иеремия возвестил в Иерусалиме Седекии, царю Иудеи,","7":"когда войско царя вавилонского осаждало Иерусалим и уцелевшие города Иудеи – Лахиш и Азеку (из всех городов Иудеи оставались только эти две крепости).","8":"Вот слово, которое было Иеремии от Господа, после того как царь Седекия заключил с народом Иерусалима договор об освобождении рабов","9":"(все должны были отпустить на свободу своих рабов – евреев и рабынь – евреек – не держать иудея, брата своего, в рабстве).","10":"Все вельможи и весь народ вступили в этот договор и согласились отпустить на свободу рабов и рабынь, не держать их больше в рабстве. Согласились и отпустили их.","11":"Но потом передумали, вернули рабов и рабынь, которых раньше отпустили на свободу, и снова сделали их рабами и рабынями.","12":"И было Иеремии слово Господа.","13":"«Так говорит Господь, Бог Израиля: когда Я вывел ваших отцов из Египта, из дома рабства, Я заключил с ними такой договор:","14":"„На седьмой год отпускай на свободу брата своего, еврея, купленного тобою; пусть он будет твоим рабом шесть лет, а затем отпусти его на свободу\". Но не слушали Меня ваши отцы, не внимали.","15":"А вы теперь раскаялись и поступили праведно предо Мною: даровали свободу своим ближним. И заключили вы договор предо Мною, в Храме, который именем Моим осенен.","16":"Но затем вы опять передумали, вы имя Мое осквернили – вернули себе рабов и рабынь, которых до этого, по их желанию, отпустили на свободу. Вы вновь сделали их своими рабами и рабынями.","17":"Потому так говорит Господь: вы не послушались Меня, не даровали свободу своим братьям, ближним своим. Теперь Я дарую вам свободу, – говорит Господь, – свободу погибнуть от меча, от мора и голода. Я сделаю вас примером страшным для всех царств земли.","18":"С людьми, что нарушили договор, которому Я был свидетель, не исполнили слов договора, заключенного предо Мною, Я поступлю так же, как они – с тем тельцом, которого они рассекли надвое и прошли между его половинами.","19":"Вельмож Иудеи, вельмож Иерусалима, евнухов, священников и весь народ страны – всех, кто прошел между половинами тельца, –","20":"Я отдам в руки врагов, в руки тех, кто жаждет их смерти, и будут их трупы пищей для птиц небесных и зверей земных.","21":"Седекию, царя Иудеи, и его вельмож Я отдам в руки врагов, в руки тех, кто жаждет их смерти, в руки воинов царя вавилонского, которые сейчас от вас отступили.","22":"По воле Моей, – говорит Господь, – враги вернутся к этому городу, осадят его, захватят и сожгут огнем. Города Иудеи Я обращу в пустыню, жителей в них не останется»."},"35":{"1":"Вот слово, которое было Иеремии от Господа во дни царя Иудеи Иоакима, сына Иосии:","2":"«Иди к рехавитам, говори с ними, приведи их в Храм Господа, в один из залов, и дай им вина».","3":"Я позвал Яазанию, сына Иеремии, сына Хаваццинии, братьев его и всех сыновей – весь род рехавитов –","4":"и привел их в Храм Господа, в зал сыновей Ханана, человека Божьего, сына Игдалии. Зал этот – возле зала вельмож, над залом Маасеи, стража порога, сына Шаллумова.","5":"Я поставил перед рехавитами кувшины с вином и чаши и сказал им: «Пейте вино».","6":"Но ответили они: «Вина мы не пьем, ибо предок наш Ионадав, сын Рехава, заповедал нам: Вина не пейте, ни вы, ни ваши дети, вовеки!","7":"Домов не стройте, хлеба не сейте, винограда не разводите, да не будет у вас этого! Во все ваши дни в шатрах живите, и жить вы будете долго на земле, где вы – пришельцы.","8":"Мы исполняем повеления нашего предка Ионадава, сына Рехава, – все, что он нам заповедал: ни мы, ни наши жены, ни сыновья, ни дочери наши никогда не пили вина,","9":"не строили себе домов, чтобы жить в них, нет у нас виноградников, полей и зерна.","10":"Мы живем в шатрах, совершаем и исполняем все, что заповедал нам предок наш Иона дав.","11":"А когда Навуходоносор, царь Вавилона, пошел войною против этой земли, мы решили уйти от войска халдеев и арамеев в Иерусалим. И вот – мы живем в Иерусалиме».","12":"И было Иеремии слово Господа.","13":"Так говорит Господь Воинств, Бог Израиля: иди и скажи людям Иудеи, жителям Иерусалима: неужели вы не поймете этого наставления, не послушаете Моих слов? – говорит Господь. –","14":"Слова Ионадава, сына Рехава, соблюдаются. Он заповедал своим сыновьям не пить вина – и они не пьют его до сих пор, повинуясь заповеди своего предка. А вы Мне не повинуетесь, хотя Я говорил вам, говорил снова и снова!","15":"Я посылал к вам рабов Моих, пророков, посылал снова и снова, с такими словами: «Пусть каждый из вас оставит злой путь свой! Сделайте добрыми ваши деяния, не поклоняйтесь богам иным, не служите им – и живите на земле, которую Я дал вам и отцам вашим». Но вы не внимали, Меня не слушали.","16":"Потомки Ионадава, сына Рехава, исполняют заповедь своего предка – то, что он им заповедал, – а этот народ Мне не повинуется!","17":"Потому так говорит Господь, Бог Воинств, Бог Израиля: Я обрушу на Иудею, на жителей Иерусалима все беды, которые Я предрек им, ибо Я говорил им, но они не слушали, звал их, но они не отвечали.","18":"Иеремия сказал рехавитам: «Так говорит Господь Воинств, Бог Израиля: за то, что вы повинуетесь заповедям вашего предка Ионадава, все заповеди его соблюдаете, все, что он вам заповедал, исполняете,","19":"за это, – так говорит Господь Воинств, Бог Израиля, – никогда не исчезнет предо Мною род Ионадава, сына Рехава»."},"36":{"1":"В четвертый год правления царя Иудеи Иоакима, сына Иосии, было Иеремии такое слово от Господа:","2":"«Возьми свиток и запиши в него все слова об Израиле, Иудее и всех народах – все, что Я говорил тебе с того дня, когда Я заговорил с тобою впервые, в правление Иосии, и доныне.","3":"Быть может, поймут потомки Иуды, какую беду Я задумал послать им, и каждый из них оставит злой путь свой. Тогда Я прощу им преступления их и грехи».","4":"Иеремия призвал Баруха, сына Нерии, и Барух под диктовку Иеремии записал в свиток все слова Господа, которые Господь говорил Иеремии.","5":"Иеремия сказал Баруху: «Я никуда не выхожу и не могу идти в Храм Господа.","6":"Иди туда ты и по свитку, который ты записал под мою диктовку, прочти там слова Господа во всеуслышание перед всем народом, что соберется в Храме Господа в день поста, – всем жителям Иудеи, которые придут туда из своих городов, прочти эти слова во всеуслышание.","7":"Быть может, они вознесут молитву к Господу и каждый из них оставит злой путь свой, ибо велики гнев и ярость, на которые Господь обрек этот народ».","8":"Барух, сын Нерии, сделал так, как велел ему пророк Иеремия, – прочел в Храме Господа свиток со словами Господа.","9":"В пятый год правления царя Иудеи Иоакима, сына Иосии, в девятом месяце, был объявлен пост пред Господом среди всех людей Иерусали – ма и людей, пришедших в Иерусалим из городов Иудеи.","10":"И Барух прочел по свитку слова Иеремии перед всем народом во всеуслышание, в Храме Господа, в зале Гемарии, сына писца Шафана, на верхнем дворе, возле Новых ворот Храма Господа.","11":"Михей, сын Гемарии, сына Шафана, слышал все слова Господа, что были в свитке.","12":"Он спустился в царский дворец, в зал писцов, а там в это время сидели вельможи: писец Элишама, Делая, сын Шемаи, Элнатан, сын Ахбора, Гемария, сын Шафана, Седекия, сын Ханании, и другие вельможи.","13":"Михей пересказал им все, что он слышал, когда Барух читал свиток перед народом во всеуслышание.","14":"Вельможи послали Иегуди, сына Нетании, сына Шелемии, сына Куши, чтобы он сказал Баруху: «Возьми свиток, который ты читал во всеуслышание перед народом, и приходи». Барух, сын Нерии, взял свиток и пришел к вельможам.","15":"Они сказали ему: «Сядь, прочти нам этот свиток». Барух прочел им.","16":"Когда вельможи услышали все эти слова, они в ужасе переглянулись и сказали Баруху: «Мы должны передать все эти речи царю!»","17":"Еще они спросили Баруха: «Скажи нам, как ты записал все это? Из уст Иеремии?»","18":"Барух ответил им: «Своими устами он говорил мне все эти слова, а я записывал их в свиток чернилами».","19":"Вельможи сказали Баруху: «Ступайте, ты и Иеремия, спрячьтесь, чтобы никто не знал, где вы».","20":"Вельможи пошли к царю, во дворец, а свиток оставили в зале писца Элишамы. Они пересказали царю все эти речи.","21":"Царь послал Иегуди, чтобы тот принес свиток. Иегуди принес свиток из зала писца Элишамы и прочел его вслух перед царем и всеми вельможами (те стояли возле царя).","22":"Царь тогда жил в своем зимнем доме (это было в девятом месяце). Перед царем пылал очаг,","23":"и как только Иегуди зачитывал три – четыре столбца, царь отрезал их ножом, которым пользуются писцы, и бросал в огонь очага, пока весь свиток не погиб в огне очага.","24":"И ни царь, ни его слуги, которые слышали все эти слова, не ужаснулись, не разорвали на себе одежды!","25":"Только Элнатан, Делая и Гемария умоляли царя не сжигать свиток, но царь не послушал их.","26":"Царь велел Иерахмеэлу, царскому сыну, Серае, сыну Азриэла, и Шелемии, сыну Авдеэла, схватить писца Баруха и пророка Иеремию, но тех укрыл Господь.","27":"После того как царь сжег свиток с речами, которые Барух записал под диктовку Иеремии, было Иеремии слово Господа:","28":"«Возьми другой свиток и запиши в него все прежние речи, что были в первом свитке, в том, который сжег Иоаким, царь Иудеи.","29":"И скажи Иоакиму, царю Иудеи: „Так говорит Господь: ты сжег этот свиток, сказав:, Напрасно ты, Иеремия, написал, что придет царь Вавилона и землю сию уничтожит, истребит на ней и людей, и животных!'","30":"Потому так говорит Господь об Иоакиме, царе Иудеи: не будут его потомки восседать на престоле Давида. Труп его будет брошен на зной дневной, на холод ночи.","31":"Я покараю Иоакима, потомков его и слуг за их преступления. Я пошлю на них, на жителей Иерусалима, на людей Иудеи все те беды, которые Я предрекал им, но они не слушали\"».","32":"Иеремия взял другой свиток и дал его писцу Баруху, сыну Нерии. Барух под диктовку Иеремии записал туда все речи первого свитка, который сжег на огне Иоаким, царь Иудеи. И много похожих речей было добавлено."},"37":{"1":"После Иехонии, сына Иоакима, царем стал Седекия, сын Иосии: Навуходоносор, царь Вавилона, сделал его царем над Иудеей.","2":"Седекия, его слуги и народ страны не повиновались словам Господа, которые Господь говорил через пророка Иеремию.","3":"Царь Седекия послал к пророку Иеремии Иегухала, сына Шелемии, и священника Софонию, сына Маасеи, чтобы они попросили его: «Помолись о нас Господу, Богу нашему!»","4":"В то время Иеремия свободно жил среди людей, его не заключали в тюрьму.","5":"Войско фараона выступило из Египта, и халдеи, осаждавшие Иерусалим, получили весть об этом и отошли от Иерусалима.","6":"И было пророку Иеремии слово Господа.","7":"Так говорит Господь, Бог Израиля: царю Иудеи, пославшему вас вопросить Меня, скажите так: войско фараона выступило вам на помощь, но оно вернется в свою страну, в Египет.","8":"И халдеи вернутся сюда, снова осадят этот город, захватят его и сожгут огнем!","9":"Так говорит Господь: не обольщайтесь, не думайте, что уйдут отсюда халдеи! Не уйдут они!","10":"Даже если бы вы разбили войско халдеев, которое воюет с вами, и остались бы у них лишь раненые, то и тогда они поднялись бы, вышли из своих шатров и сожгли бы этот город огнем.","11":"Когда войско халдеев отошло от Иерусалима, отступая перед войском фараона,","12":"Иеремия вышел из Иерусалима, чтобы идти в землю Вениаминову – бежал из города вместе с народом.","13":"Но когда Иеремия проходил через Вениаминовы ворота, находившийся там начальник стражи по имени Ирия, сын Шелемии, сына Ханании, схватил пророка Иеремию и сказал: «Ты хочешь перебежать к халдеям!»","14":"Иеремия ответил: «Ложь! Я не бегу к халдеям». Но Ирия его не слушал. Он схватил Иеремию и привел к вельможам.","15":"Вельможи были разгневаны на Иеремию. Они избили его и заключили под стражу, в дом писца Ионафана (этот дом сделали тюрьмой).","16":"Так Иеремия оказался в подземной темнице и просидел там много дней.","17":"Царь Седекия послал за Иеремией. Того привели во дворец, и царь тайно спросил его: «Было ли слово от Господа?» Иеремия ответил: «Было!» И сказал Иеремия: «Ты попадешь в руки царя вавилонского».","18":"Иеремия также сказал царю Седекии: «Чем я виноват перед тобою, перед твоими слугами и всем этим народом, за что вы бросили меня в тюрьму?","19":"Где же ваши пророки, которые вам вещали: „Не придет к вам царь Вавилона, на землю эту!\"?","20":"О владыка мой, царь, послушай меня, мольбу мою не отвергни! Не отправляй меня назад, в дом писца Ионафана, ведь я умру там».","21":"По приказу царя Седекии Иеремию отправили на двор стражи. Там ему выдавали в день по одной лепешке с улицы пекарей, пока не кончился весь хлеб в городе. Итак, Иеремия оставался на дворе стражи."},"38":{"1":"Шефатия, сын Маттана, Гедалия, сын Пашхура, Иегухал, сын Шелемии, и Пашхур, сын Малкии, слышали, как Иеремия говорил всему народу такие слова:","2":"«Так говорит Господь: кто останется в этом городе, тот умрет – от меча, от голода и мора. Кто выйдет к халдеям, тот останется жив – жизнь и будет ему наградой, будет он жить!","3":"Так говорит Господь: этот город будет отдан войску царя вавилонского, царь захватит город!»","4":"Вельможи сказали царю: «Надо убить этого человека, ибо он, говоря такие слова, ослабляет воинов, оставшихся в городе, и весь народ! Не добра он желает народу, а только зла».","5":"Царь Седекия сказал: «Он в ваших руках, ведь царь перед вами бессилен!»","6":"Иеремию схватили и бросили в яму для воды (эта яма на дворе стражи принадлежала царскому сыну Малкии). Иеремию спустили туда на веревках. В яме тогда не было воды, а только жидкая грязь, и в эту грязь Иеремия погрузился.","7":"Эведмелех, кушит, евнух при царском дворце, услыхал, что Иеремию бросили в яму. Царь в это время сидел у Вениаминовых ворот.","8":"Эведмелех вышел из царского дворца и сказал царю:","9":"«Владыка мой, царь! То, что сделали эти люди с пророком Иеремией, – злодейство! Они бросили его в яму, и он умрет там от голода, ведь в городе нет уже хлеба».","10":"Царь приказал Эведмелеху, кушиту: «Возьми отсюда тридцать человек и подними пророка Иеремию из ямы, пока он не умер».","11":"Эведмелех взял с собою людей и пришел в царский дворец, в кладовую одежды. Он забрал оттуда старые тряпки и изношенную одежду и спустил все это на веревках в яму к Иеремии.","12":"Эведмелех, кушит, сказал Иеремии: «Обвяжи себя веревкой под мышками, а под веревку подложи старые тряпки и изношенную одежду». Иеремия так и сделал.","13":"Стали поднимать Иеремию на веревках и вытащили его из ямы. И остался Иеремия на дворе стражи.","14":"Царь Седекия послал за ним. Привели пророка Иеремию к третьему входу Храма Господа, и там царь сказал Иеремии: «Я спрошу тебя, а ты ничего от меня не скрывай».","15":"Иеремия ответил Седекии: «Если я скажу тебе, разве ты не предашь меня смерти? Если посоветую, ты меня не послушаешь».","16":"Царь Седекия тайно поклялся Иеремии: «Жив Господь, который дал нам жизнь! Я не предам тебя смерти и не отдам в руки тех, кто жаждет твоей смерти».","17":"И сказал Иеремия Седекии: «Так говорит Господь, Бог Воинств, Бог Израиля: если ты выйдешь к военачальникам царя вавилонского, ты спасешь свою жизнь, и город этот не будет сожжен огнем. Ты останешься жив, вместе со всем своим домом.","18":"Если же не выйдешь к военачальникам царя вавилонского, этот город будет отдан халдеям, они сожгут его огнем, и сам ты не спасешься от их рук».","19":"Царь Седекия ответил Иеремии: «Я боюсь иудеев, которые перебежали к халдеям. Если меня выдадут им, они надо мной надругаются».","20":"Иеремия сказал: «Не выдадут! Повинуйся словам Господа, которые я возвещаю тебе, и будешь ты благополучен, спасешь свою жизнь.","21":"Если же ты откажешься выйти из города – то слушай, какое видение явил мне Господь:","22":"вот, всех жен, оставшихся во дворце царя Иудеи, уводят к военачальникам царя вавилонского, и говорят эти женщины: Подстрекали тебя, убедили друзья твои! А когда увяз ты в трясине, они бежали.","23":"Всех твоих жен и сыновей уведут к халдеям, и сам ты не спасешься от рук халдеев, будешь схвачен царем Вавилона, а город этот будет сожжен огнем».","24":"Седекия сказал Иеремии: «Пусть никто не узнает об этом, и тогда ты останешься жив.","25":"Если вельможи прослышат, что я говорил с тобою, придут к тебе и скажут: „Расскажи-ка, что ты сказал царю и что царь сказал тебе; ничего от нас не скрывай, иначе мы убьем тебя\", –","26":"ответь им: „Я умолял царя не возвращать меня в дом Ионафана, на верную смерть\"».","27":"И пришли к Иеремии вельможи, стали его расспрашивать. Иеремия ответил им так, как велел царь. И вельможи больше ни о чем его не спросили, ведь никто не знал, о чем был тот разговор.","28":"Иеремия оставался на дворе стражи до того дня, когда Иерусалим был взят. И вот, Иерусалим был взят."},"39":{"1":"В девятый год правления Седекии, царя Иудеи, в десятом месяце, Навуходоносор, царь Вавилона, со всем своим войском подошел к Иерусалиму и осадил его.","2":"В одиннадцатый год правления Седекии, в девятый день четвертого месяца, городская стена была проломлена.","3":"Вельможи царя вавилонского вошли в город и воссели у Средних ворот. Это были: Нергал – сар – эцер из Самгара, Неву - сар – сехим, начальник евнухов, Нергал – сар – эцер, военачальник, и все остальные вельможи царя вавилонского.","4":"Увидев это, Седекия, царь Иудеи, и все воины бежали – ночью они вышли из города возле царского сада, через Ворота Двух Стен, и пошли по дороге на Араву .","5":"Войско халдеев пустилось за ними в погоню и настигло Седекию в пустыне близ Иерихона. Схватили Седекию и привели к Навуходоносору, царю Вавилона, в Ривлу, что в земле Хамат, и там Навуходоносор устроил над ним суд.","6":"В Ривле, на глазах у Седекии, царь Вавилона зарезал его сыновей, и всю знать Иудеи перебил царь вавилонский.","7":"Затем он ослепил Седекию, заковал его в кандалы и увел в Вавилон.","8":"Царский дворец и дома простолюдинов халдеи сожгли дотла, а стены Иерусалима разрушили.","9":"Всех, кто еще уцелел в городе, включая перебежчиков, перешедших на сторону вавилонского царя, – всех, кто уцелел, Навузарадан, начальник телохранителей, отправил в Вавилон.","10":"Лишь часть бедняков, тех, у кого ничего не было, Навузарадан, начальник телохранителей, оставил в Иудее и дал им тогда виноградники и поля.","11":"Навуходоносор, царь Вавилона, отдал Навузарадану, начальнику телохранителей, такой приказ об Иеремии:","12":"«Забери его и позаботься о нем. Не делай ему никакого зла; как он тебе скажет, так и поступи с ним».","13":"Навузарадан, начальник телохранителей, а также Неву - шаз – бан, начальник евнухов, Нергал – сар – эцер, военачальник, и остальные вельможи царя вавилонского","14":"послали за Иеремией. Они забрали его со двора стражи и передали Гедалии, сыну Ахикама, сына Шафана, чтобы тот отправил Иеремию домой. Так Иеремия остался среди своего народа.","15":"Когда Иеремия был еще в заключении на дворе стражи, было ему слово Господа:","16":"«Иди и скажи Эведмелеху, кушиту: так говорит Господь Воинств, Бог Израиля: теперь Я исполню слова Мои об этом городе, не на благо ему, а на горе! Настанет день, и ты увидишь это воочию.","17":"Но тебя Я избавлю в тот день, – говорит Господь, – ты не попадешь в руки людей, которых ты боишься,","18":"ибо Я спасу тебя. Ты не падешь от меча, жизнь и будет тебе наградой, ибо ты на Меня уповал, – говорит Господь»."},"40":{"1":"Вот слово, которое было Иеремии от Господа, после того как Навузарадан, начальник телохранителей, отпустил Иеремию из Рамы (Навузарадан отыскал Иеремию, закованного в кандалы, среди пленников, угоняемых из Иерусалима и Иудеи в Вавилон).","2":"Привели Иеремию к начальнику телохранителей, и тот сказал Иеремии: «Господь, Бог твой, предрек беду этому месту.","3":"И теперь исполнил, совершил Господь то, о чем говорил, ибо вы грешили пред Господом, голосу Его не повиновались – потому и случилось с вами все это.","4":"Но сегодня я освобождаю тебя от оков, что на твоих руках. Если хочешь идти со мною в Вавилон, иди, и я позабочусь о тебе; если же не хочешь идти со мною в Вавилон, оставайся. Смотри, вся страна пред тобою – куда захочешь и сочтешь нужным идти, туда и иди.","5":"Если ты останешься, то возвращайся к Гедалии, сыну Ахикама, сына Шафана, которого царь вавилонский назначил правителем над городами Иудеи. Живи при нем, среди этого народа, или же иди, куда сочтешь нужным». Начальник телохранителей дал Иеремии еды и подарок и отпустил его.","6":"Иеремия пришел в Мицпу к Гедалии, сыну Ахикама, и жил при нем, среди людей, которые были оставлены в стране.","7":"Военачальники, которые скрывались со своими людьми в пустыне, узнали, что царь Вавилона назначил Гедалию, сына Ахикама, правителем над страной, правителем над мужчинами, женщинами и детьми – самыми бедными жителями страны, которые не были угнаны в Вавилон.","8":"И пришли к Гедалии, в Мицпу, со своими людьми Измаил, сын Нетании, Иоханан и Ионафан, сыновья Кареаха, Серая, сын Танхумета, сыновья Эфая из Нетофы , Иезания из Маахи .","9":"Гедалия, сын Ахикама, сына Шафана, поклялся им и их людям: «Не бойтесь халдейских чиновников, оставайтесь в стране, служите царю Вавилона, и будет вам хорошо!","10":"Я остаюсь в Мицпе, чтобы служить халдеям, которые приходят к нам, а вы запасайте вино, смоквы и оливковое масло, наполняйте ваши сосуды и живите в городах, которыми вы завладели».","11":"Иудеи в Моаве, в стране сынов Аммона, в Эдоме и в остальных странах также услыхали, что царь вавилонский оставил часть народа в Иудее и назначил там правителем Гедалию, сына Ахикама, сына Шафана.","12":"Вернулись эти иудеи из тех мест, куда прежде бежали. Они пришли в Иудею, к Гедалии в Мицпу, и появились у них в изобилии вино и смоквы.","13":"Иоханан, сын Кареаха, и все военачальники, которые скрывались в пустыне, пришли к Гедалии в Мицпу.","14":"Они сказали Гедалии: «Неужели ты не знаешь, что Баалис, царь аммонитян, послал Измаила, сына Нетании, чтобы тот убил тебя?» Но Гедалия, сын Ахикама, не поверил им.","15":"Иоханан, сын Кареаха, тайно сказал Гедалии в Мицпе: «Позволь, я пойду и убью Измаила, сына Нетании, и никто ничего не узнает! Зачем допускать, чтобы он убил тебя и все иудеи, которые собрались к тебе, снова были рассеяны, чтобы остаток Иуды погиб?»","16":"Гедалия, сын Ахикама, ответил Иоханану, сыну Кареаха: «Не делай этого! Неправду ты говоришь об Измаиле»."},"41":{"1":"В седьмой месяц в Мицпу, к Гедалии, сыну Ахикама, пришел Измаил, сын Нетании, сына Элишамы, царский родственник из числа царских сановников, и с ним десять человек. Гедалия и Измаил вместе пировали в Мицпе.","2":"И вот, Измаил, сын Нетании, и десять человек, что были при нем, поднялись и убили мечами Гедалию, сына Ахикама, сына Шафана, – убили того, кого царь вавилонский назначил правителем над страной.","3":"И всех иудеев, которые были с Гедалией в Мицпе, убил Измаил, а также воинов – халдеев, которые там находились.","4":"На следующий день после убийства Гедалии, когда еще никто ничего не знал,","5":"пришли восемьдесят человек из Шехема, Силома и Самарии. Бороды у них были сбриты, одежды разорваны, тела покрыты порезами. Они несли хлебные дары и благовония для дома Господа.","6":"Измаил, сын Нетании, вышел из Мицпы им навстречу. Он шел и плакал, а когда приблизился к ним, сказал: «Идите к Гедалии, сыну Ахикама».","7":"Как только они вошли в город, Измаил, сын Нетании, со своими людьми перебил их, а трупы бросил на дно ямы для воды.","8":"Десять человек из этих восьмидесяти взмолились к Измаилу: «Не убивай нас! Есть у нас тайники за городом, там – зерно, ячмень, оливковое масло и мед». Измаил не стал убивать их, как остальных.","9":"Яма для воды, куда Измаил бросил трупы убитых им людей, была той большой ямой, которую сделал некогда царь Аса, обороняясь от Баши, царя израильского. Эту яму Измаил, сын Нетании, наполнил убитыми.","10":"Измаил увел из Мицпы в плен всех оставшихся там людей – и царских дочерей, и всех прочих людей, оставшихся в Мицпе, над которыми Навузарадан, начальник телохранителей, поставил Гедалию, сына Ахикама. Измаил, сын Нетании, взял их в плен и повел к аммонитянам.","11":"Иоханан, сын Кареаха, и его военачальники узнали, какое злодеяние совершил Измаил, сын Нетании.","12":"Они собрали людей и вышли, чтобы сразиться с Измаилом, сыном Нетании. Настигли они его у Большого пруда, что в Гаваоне.","13":"Люди, захваченные Измаилом, возликовали, увидев Иоханана, сына Кареаха, и его военачальников.","14":"Все люди, которых Измаил угнал из Мицпы, повернули назад и присоединились к Иоханану, сыну Кареаха.","15":"Но сам Измаил, сын Нетании, с восемью своими людьми ускользнул от Иоханана и ушел к аммонитянам.","16":"Иоханан, сын Кареаха, и его военачальники забрали с собою всех оставшихся людей, которых Измаил, сын Нетании, после убийства Гедалии, сына Ахикама, угнал из Мицпы, – мужчин, способных носить оружие, женщин, детей и евнухов. Иоханан забрал их из Гаваона,","17":"и отправились они в путь. Они остановились в Геруг – Кимгаме, близ Вифлеема, чтобы затем бежать в Египет –","18":"от халдеев, которых они боялись. Ведь Гедалию, сына Ахикама, убитого Измаилом, сыном Нетании, сам вавилонский царь назначил правителем над страной."},"42":{"1":"Все военачальники, Иоханан, сын Кареаха, Азария, сын Хошаи, и весь народ, от мала до велика, пришли","2":"и сказали пророку Иеремии: «Исполни нашу мольбу! Помолись о нас Господу, Богу твоему, помолись об этих уцелевших людях! Ты видишь, немного нас осталось, а были мы многочисленны.","3":"Пусть укажет нам Господь, Бог твой, какой путь нам избрать и что делать».","4":"Пророк Иеремия ответил: «Я внял вашей мольбе, я помолюсь Господу, Богу вашему, как вы просите. Все, что ответит вам Господь, я возвещу вам, не утаю ни слова».","5":"Они сказали Иеремии: «Да будет Господь нам свидетелем, правдивым и верным: мы все сделаем так, как скажет нам через тебя Господь, Бог твой!","6":"Будь то доброе слово или злое, мы подчинимся голосу Господа, Бога нашего, к которому мы тебя посылаем. И будем мы благополучны, повинуясь голосу Господа, Бога нашего».","7":"Через десять дней было Иеремии слово Господа.","8":"Призвал Иеремия Иоханана, сына Кареаха, и всех его военачальников, и весь народ, от мала до велика,","9":"и сказал им: «Так говорит Господь, Бог Израиля, к которому вы посылали меня, чтобы я молился о вашем прошении:","10":"если вы останетесь на этой земле, Я укреплю вас и не разрушу, насажу вас и не вырву, ибо Я сожалею о беде, которую Я послал вам.","11":"Не бойтесь царя вавилонского, которого вы боитесь, не бойтесь его! – говорит Господь. – Ибо Я с вами, Я спасу вас, от его руки вас избавлю.","12":"Милостью Я одарю вас, и он вас помилует, вернет вас на вашу землю.","13":"Если же вы, не повинуясь голосу Господа, Бога вашего, скажете: „Мы не будем жить на этой земле\", –","14":"если скажете: „Мы пойдем в Египет, и там войны не увидим, боевой трубы не услышим, голодать не будем, там станем жить!\" –","15":"то слушай такое слово Господа, остаток Иуды! Так говорит Господь Воинств, Бог Израиля: если вы решите уйти в Египет, придете туда и там поселитесь,","16":"то меч, которого вы боитесь, настигнет вас там, в Египте, и голод, которого вы страшитесь, последует за вами туда, в Египет, и там вы умрете!","17":"Все люди, решившие идти в Египет, чтобы там поселиться, умрут от меча, от голода и мора. Никто из них не уцелеет, не сможет убежать от беды, которую Я пошлю им.","18":"Так говорит Господь Воинств, Бог Израиля: яростный гнев Мой пролился на жителей Иерусалима, так и на вас прольется Моя ярость, когда вы придете в Египет! Вы будете обречены на проклятие и ужас, поношение и позор, и не увидите вы больше этого места.","19":"Остаток Иуды! Господь сказал вам: „Не идите в Египет!\" Знайте, что сегодня я предостерег вас.","20":"Вы согрешили против самих себя! Ведь вы послали меня к Господу, Богу вашему, сказав: „Помолись о нас Господу, Богу нашему, и все, что скажет Господь, Бог наш, возвести нам – мы все исполним\".","21":"И сегодня я возвестил вам это, но вы не повинуетесь голосу Господа, Бога вашего, всему тому, что Он повелел вам через меня.","22":"Знайте же, что вы умрете от меча, от голода и мора – в том месте, куда вы хотите идти, чтобы там поселиться!»"},"43":{"1":"Иеремия возвестил всему народу слово Господа, Бога их, то слово, которое Господь, Бог их, послал народу через Иеремию.","2":"Тогда Азария, сын Хошаи, и Иоханан, сын Кареаха, со всеми дерзкими людьми сказали Иеремии так: «Ты лжешь! Не посылал тебя Господь, Бог наш, чтобы ты говорил: „Не идите в Египет, не селитесь там!\"","3":"Это Барух, сын Нерии, подстрекает тебя против нас, чтобы отдать нас в руки халдеев и погубить нас, чтобы угнали нас в Вавилон».","4":"Иоханан, сын Кареаха, военачальники и весь народ не послушались повеления Господа – остаться в Иудее.","5":"Иоханан, сын Кареаха, и военачальники забрали всех уцелевших иудеев, тех, что вернулись жить в Иудею, покинув земли народов, среди которых они были рассеяны, –","6":"забрали мужчин, женщин, детей, царских дочерей, всех людей, которых Навузарадан, начальник телохранителей, оставил с Гедалией, сыном Ахикама, сына Шафана, а также пророка Иеремию и Баруха, сына Нерии,","7":"и пошли в Египет, не повинуясь голосу Господа. Пришли они в Тахпанхес.","8":"В Тахпанхесе было Иеремии такое слово Господа:","9":"«Возьми большие камни и на глазах у иудеев спрячь их в глине возле кирпичной стены у входа во дворец фараона в Тахпанхесе.","10":"И скажи иудеям: так говорит Господь Воинств, Бог Израиля: Я приведу сюда раба Моего Навуходоносора, царя вавилонского, и поставлю престол его на этих камнях, которые Я спрятал, и царь натянет над ними свой царский полог!","11":"Придет он и разорит Египет: одни умрут, другие пойдут в плен, третьи падут от меча.","12":"Я предам огню храмы египетских богов, и одних богов царь сожжет, других уведет в плен! Как пастух надевает свою одежду, так Навуходоносор наденет на себя Египет – и уйдет спокойно.","13":"Разобьет он столбы в Доме Солнца, что в Египте, храмы египетских богов сожжет огнем»."},"44":{"1":"Вот слово, которое было Иеремии для всех иудеев, живущих в Египте – в Мигдоле, Тахпанхесе, Нофе и в земле Патрос.","2":"«Так говорит Господь Воинств, Бог Израиля: вы видели, какую беду Я послал Иерусалиму и всем городам Иудеи, – сегодня они лежат в руинах, жителей в них не осталось.","3":"Ибо они творили зло, Меня гневили: они поклонялись, воскуряли и служили богам иным, которых ни они, ни вы, ни отцы ваши не знали.","4":"Я посылал к вам рабов Моих, пророков, посылал снова и снова, с такими словами: „Не делайте эту мерзость, Я ненавижу ее!\"","5":"Но не слушали они, не внимали, от зла своего не отступались, богам иным воскуряли!","6":"Излился Мой яростный гнев, пылал он в городах Иудеи, на улицах Иерусалима, и ныне города эти стали развалинами и пустыней.","7":"Почему же и теперь, – так говорит Господь, Бог Воинств, Бог Израиля, – вы творите великое зло против самих себя, отсекаете себя от Иуды – муж – чину и женщину, ребенка и младенца, так что никто из вас не уцелеет?","8":"Вы гневите Меня делами рук своих, воскуряете богам иным в Египте, куда вы пришли, чтобы там поселиться. Вы погубите себя, обречете себя на проклятие и позор у всех народов земли!","9":"Неужели вы забыли о злодействах ваших отцов, о злодействах царей Иудеи и царских жен, о ваших злодействах, о злодействах ваших жен, обо всем, что творилось в Иудее, на улицах Иерусалима?","10":"До сих пор вы не смирились, не боитесь, не живете по Закону Моему, по Моим установлениям, которые Я дал вам и вашим отцам.","11":"Потому так говорит Господь Воинств, Бог Израиля: на горе Я обращаю к вам Мой взор! Я истреблю всех иудеев!","12":"Я погублю уцелевших иудеев, которые решили идти в Египет и там поселиться, – все они погибнут, умрут в Египте! От меча и голода они погибнут, большие и малые, от меча и голода умрут. И станут они примером проклятия и ужаса, поношения и позора.","13":"Я покараю живущих в Египте, как покарал Я Иерусалим, – мечом, голодом и мором.","14":"Никто из уцелевших иудеев, которые пришли в Египет и там поселились, не выживет, не спасется, не вернется в Иудею. Всей душой хотят они вернуться и жить в Иудее, но не вернутся, кроме беглецов немногих».","15":"Все мужчины, которые знали, что их жены воскуряют богам иным, все женщины, стоявшие там большой толпою, весь народ – те, кто жил в Египте, в Патросе, – сказали Иеремии в ответ:","16":"«Мы не станем слушать тебя, не станем слушать то слово, которое ты вещаешь нам от имени Господа!","17":"Мы будем и дальше делать все то, что мы клялись делать, – воскурять Владычице неба и совершать ей возлияния – как прежде делали мы и отцы наши, цари и вожди наши в городах Иудеи, на улицах Иерусалима. Ведь тогда мы досыта ели, счастливы были и горя не знали!","18":"А с тех пор как мы перестали воскурять Владычице неба и совершать ей возлияния, мы бедствуем, от меча и голода гибнем».","19":"А женщины сказали: «Когда мы воскуряем Владычице неба и совершаем ей возлияния, разве без ведома наших мужей мы готовим для нее жертвенный хлеб с ее изображением и совершаем ей возлияния?»","20":"Иеремия сказал всему народу – мужчинам и женщинам, всем людям, которые возражали ему, – сказал он так:","21":"«Не эти ли воскурения, которые вы совершали в городах Иудеи, на улицах Иерусалима, вы и отцы ваши, цари и вожди ваши и народ страны, – не эти ли воскурения Господь вам припомнил, не они ли достигли Его сердца?","22":"Не мог Господь больше терпеть ваши злодейства, мерзости, которые вы творили, и теперь ваша земля превратилась в пустыню, в ужас и проклятие, жителей на ней не осталось!","23":"За то, что вы воскуряли, грешили пред Господом, не повиновались голосу Господа, не жили по Его Закону, по Его установлениям и повелениям, – за это и обрушилось на вас ныне бедствие».","24":"Иеремия сказал всему народу, всем женщинам: «Слушайте слово Господа, все иудеи в Египте!","25":"Так говорит Господь Воинств, Бог Израиля: то, что вы и ваши жены говорили, то вы и делаете. Говорили вы: „Мы исполним обеты, которые дали, – будем воскурять Владычице неба, совершать ей возлияния!\" Так исполняйте, исполняйте свои обеты, храните обеты ваши!","26":"Потому слушайте слово Господа, все иудеи, живущие в Египте! Клянусь Моим великим именем, – говорит Господь, – имя Мое больше не прозвучит в устах иудеев в Египте, никто из них не скажет: „Жив Господь Бог!\"","27":"Я не спущу с вас глаз, но не на благо вам, а на горе, и будут иудеи в Египте гибнуть от меча и голода, пока совсем не исчезнут.","28":"Лишь немногие спасутся от меча и вернутся из Египта в Иудею, и тогда остаток Иуды, пришедший в Египет, чтобы там поселиться, узнает, чье исполняется слово, Мое или его!","29":"И вот вам знак, – говорит Господь, – что Я покараю вас на этом месте. Знайте, что исполнятся слова Мои вам на горе!","30":"Так говорит Господь: Я отдаю фараона Хофра, царя египетского, в руки врагов его, в руки тех, кто жаждет его смерти, как Я отдал Седекию, царя Иудеи, в руки врага его – Навуходоносора, царя вавилонского, который жаждал его смерти»."},"45":{"1":"Вот что сказал пророк Иеремия Баруху, сыну Нерии, когда тот в четвертый год правления царя Иудеи Иоакима, сына Иосии, записал из уст Иеремии все эти речи в свиток.","2":"«Так говорит Господь, Бог Израиля, о тебе, Барух:","3":"Ты говоришь: „Горе мне! Боль и скорбь мою Господь умножил, я от стонов своих изнемог, не нахожу покоя\".","4":"Но скажи ему: „Так говорит Господь: Я разрушу то, что сам Я построил, вырву то, что Я насадил, по всей земле этой!","5":"Ты просишь для себя слишком многого. Не проси, ибо Я пошлю бедствие на все живое, – говорит Господь. – Но тебе, куда бы ты ни пошел, Я сохраню жизнь, она и будет тебе наградой\"»."},"46":{"1":"Вот слово Господа о народах, которое было пророку Иеремии.","2":"О Египте, о войске фараона Нехо, царя египетского, которое стояло возле реки Евфрат, у Каркемиша, и было разбито Навуходоносором, царем Вавилона, в четвертый год правления царя Иудеи Иоакима, сына Иосии.","3":"Готовьте щиты и пики, на битву спешите,","4":"коней седлайте, мчитесь, всадники! Шлемы надев, становитесь, копья свои заточите, в броню оденьтесь!","5":"Что же Я вижу? Они трепещут, обратились в бегство, могучие воины их перебиты. Бегут, бегут они без оглядки, кругом – ужас! – говорит Господь. –","6":"Не убежит быстрый, не спасется сильный! На севере, у реки Евфрат, споткнулись они и пали.","7":"Кто это, словно Нил, поднялся? Словно бурный поток, воды его бушуют.","8":"Египет, словно Нил, поднялся, словно поток, воды его бушуют! Он сказал: «Поднимусь я, покрою землю, погублю города и живущих там!»","9":"Скачите, кони, колесницы, мчитесь! Пусть могучие воины выходят: кушиты и ливийцы со щитами, лидийцы с натянутым луком!","10":"Этот день – день Господа, Бога Воинств, день отмщенья, когда Он врагам отплатит! Меч насытится, напьется их кровью – это жертва Господу, Богу Воинств, в северной стране, у реки Евфрат.","11":"Ступай в Галаад, принеси бальзам, о дева, дочь Египта! Но напрасно лекарства ты собираешь, нет тебе исцеленья.","12":"О позоре твоем услыхали народы, крик твой по всей земле раздается! Ибо воины один за другим споткнулись и пали разом.","13":"Вот слово, которое возвестил Господь пророку Иеремии, – о том, что Навуходоносор, царь Вавилона, придет и разорит Египет.","14":"Расскажите об этом в Египте, в Мигдоле объявите, объявите в Нофе и Тахпанхесе, говорите так: «Становитесь, готовьтесь, ибо меч все вокруг пожирает!»","15":"Почему же Бык ваш повержен, почему не устоял он? Это Господь его низринул.","16":"Поверг Он многих, падают они один на другого и говорят друг другу: «Вставайте, к народу нашему вернемся, на землю нашу родную, спасемся от мечей жестоких!»","17":"Фараону, царю Египта, такое имя дайте: Болтун – Упустивший – Время.","18":"Клянусь Собою, – говорит Царь, чье имя Господь Воинств, – что придет к вам тот, кто – как Фавор средь гор, как Кармил над морем!","19":"Собирай свои вещи, готовься к изгнанью, жительница Египта! Ибо Ноф в пустыню превратится, будет он разрушен, жителей в нем не останется.","20":"Египет – красивая корова, с севера летит, летит к ней овод!","21":"И наемники в Египте – что быки тучные, но они обратились в бегство, бегут, устоять не могут, ибо день погибели к ним пришел, час расплаты.","22":"Как змея, шипит Египет, уползает, ведь идут враги на него войною, с топорами к нему подходят, словно лесорубы.","23":"Его лес они срубили, – говорит Господь, – лес непроходимый, ведь их больше, чем саранчи, числа им нет!","24":"Опозорена дочь Египта, народу северному отдана в руки.","25":"Сказал Господь Воинств, Бог Израиля: Я покараю Амона в Но, фараона и весь Египет, богов и царей Египта, фараона и всех, кто на него уповает!","26":"Я отдам их в руки тех, кто жаждет их смерти, в руки Навуходоносора, царя вавилонского, и его слуг. Но после этого будет жить Египет, как в прежние дни, – говорит Господь.","27":"А ты, раб Мой Иаков, не бойся, не страшись, Израиль! Я спасу тебя, верну из страны далекой, потомков твоих – из страны плена. Вернется Иаков, будет жить безмятежно и мирно, и врагов у него не будет.","28":"А ты, раб Мой Иаков, не бойся, – говорит Господь, – ибо Я с тобою! Я уничтожу все народы, средь которых тебя рассеял. Лишь тебя Я не уничтожу, но покараю тебя по заслугам, без наказанья тебя не оставлю!"},"47":{"1":"Вот слово Господа о филистимлянах, которое было пророку Иеремии, прежде чем фараон разорил Газу.","2":"Так говорит Господь: с севера надвигаются воды, хлынут они рекою, затопят землю и все, что на ней есть, города и живущих там! Зарыдают люди, жители страны заплачут","3":"от стука копыт лошадиных, от грохота колесниц, от шума колес их! И отцы на детей не взглянут, ибо руки лишатся силы","4":"в тот день, что настанет филистимлянам всем на погибель, на гибель последним союзникам Сидона и Тира. Господь истребит филистимлян, остаток народа с берегов Кафтора!","5":"Газа голову свою обреет, Ашкелон умолкнет. Уцелевшие жители долины, доколе будете наносить себе раны?","6":"О горе! Меч Господень, когда же ты успокоишься? В ножны вернись, остановись, утихни!","7":"О если бы ты успокоился! Но Господь ему дал повеленье, на Ашкелон, на побережье морское Господь меч Свой направил!"},"48":{"1":"О Моаве. Так говорит Господь Воинств, Бог Израиля: о Нево! Горе ему, он разграблен! Опозорен, взят Кирьятаим, опозорена, разрушена крепость.","2":"Погибла слава Моава, в Хешбоне против него замышляют зло: «Пойдем, уничтожим это племя!» И ты, Мадмен, погибнешь, меч тебя настигнет.","3":"Плач из Хоронаима раздается: «Грабеж, разгром великий!»","4":"Опустошен Моав, его дети малые рыдают.","5":"На подъеме к Лухиту не смолкают рыданья, на спуске к Хоронаиму слышны горькие, скорбные стоны.","6":"Бегите, жизни свои спасайте! И будете вы подобны колючему кустарнику в пустыне.","7":"Ибо на дела свои и сокровища вы уповали, потому и попадете в неволю. Отправится Кемош в изгнанье, и жрецы его, и вельможи.","8":"Грабитель придет в каждый город: не спасется город, погибнет долина, опустеет равнина, ибо так сказал Господь.","9":"Солью Моав посыпьте, будет он уничтожен! Города его станут пустыней, жителей в них не останется.","10":"Проклят, кто о деле Господа не радеет, проклят, кто меч не обагрит кровью!","11":"С юных лет был Моав безмятежен, как вино, что покоится над осадком. Из сосуда в сосуд его не переливали, в плен не угоняли – и вкус его оставался прежним, не менялось благоуханье.","12":"Потому дни настанут, – говорит Господь, – когда Я пошлю виночерпиев, и они его выльют, опустошат сосуды, разобьют кувшины!","13":"Посрамлен будет Моав из-за Кемоша, как Израиль был посрамлен из-за Бет – Эля, своей надежды.","14":"Напрасно вы говорите: «Мы сильны! Мы воины, могучие в битве!»","15":"Разорен Моав, города его взяты, юноши лучшие пошли на закланье, – говорит Царь, чье имя Господь Воинств. –","16":"Близка погибель Моава, спешат к нему беды.","17":"Плачьте о нем, соседи, все, кто имя его знает! Говорите: «О горе! Сломан посох могучий, жезл славы».","18":"О почете забудь, на иссохшую землю сядь, жительница Дивона! Идет к тебе опустошитель Моава, он твердыни твои разрушит.","19":"Стой и гляди на дорогу, жительница Ароэра, окликай беглецов уцелевших, спрашивай: «Что случилось?»","20":"Опозорен Моав, уничтожен! Рыдайте и плачьте, при Арноне провозгласите, что Моав разграблен,","21":"что свершился суд над равниной, над Холоном, Яхцой, Мефаатом,","22":"над Дивоном и над Нево, над Бет – Дивлатаимом,","23":"над Кирьятаимом, над Бет – Гамулом и Бет – Меоном,","24":"над Керийотом, Боцрой, над каждым городом моавитским, и дальним и ближним.","25":"Рог Моава обрублен, рука его сломана, – говорит Господь. –","26":"Допьяна его напоите, ибо против Господа он возносился! Пусть в блевотине своей он хлопает руками, пусть он сам посмешищем станет.","27":"Не ты ли над Израилем потешался, будто в воровстве его уличили? О нем говорил ты, головой качая!","28":"Города свои оставьте, средь скал ютитесь, жители Моава! Станьте как дикие голуби, что гнезда вьют над пропастью.","29":"О гордости Моава мы слыхали, о том, как он горд, о высокомерии его, гордости, горделивости, о дерзком его сердце.","30":"Я знаю, – говорит Господь, – его необузданность! Хвастовство его – ложь пустая, и дела его – ложь.","31":"Потому о Моаве я плачу, рыдаю обо всем Моаве, о людях Кир – Хереса стенаю.","32":"Горестней, чем о Язере, плачу я о тебе, виноградник Сивмы ! Лоза твоя тянулась за море, Язера достигала. Смоквы твои и виноградные грозди срывает грабитель.","33":"Лишилась радости и веселья земля Моава – сад цветущий! Давильни Я без вина оставил, никто виноград не давит с радостным криком. Крик стоит, да не радостный!","34":"От Хешбона до Эльале раздаются рыданья, слышны крики до самой Яхцы, от Цоара до Хоронаима, до Эглат – Шелишии , ибо и воды Нимрима иссякнут.","35":"Я истреблю в Моаве, – говорит Господь, – всех, кто в капищах приносит жертвы, кто богам своим воскуряет!","36":"Потому мое сердце, как свирель, о Моаве плачет! О людях Кир – Хереса мое сердце, словно свирель, плачет, ибо все достоянье их погибло.","37":"Головы их обриты, бороды – срезаны, у каждого на руках – порезы, на бедрах – дерюга.","38":"На каждой крыше в Моаве, на каждой улице слышны рыданья. Я разбил Моав, словно сосуд ненужный, – говорит Господь.","39":"Плачут о нем: «О горе! Он разбит! О горе! Моав обратился в бегство, покрыт позором!» В посмешище Моав превратился, стал для всех соседей примером страшным.","40":"Так говорит Господь: устремится орел на добычу, над Моавом раскинет крылья!","41":"Города Моава будут взяты, крепости – захвачены. И в тот день моавитские воины затрепещут, словно роженицы!","42":"Погибнет народ Моава, ибо против Господа он возносился.","43":"Ужас, яма и сети – вот удел ваш, моавитяне, – говорит Господь. –","44":"Кто побежит от ужаса, тот упадет в яму, кто из ямы станет выбираться, тот попадется в сети, ибо Я пошлю Моаву год кары, – говорит Господь. –","45":"Под сенью стен Хешбона остановились беглецы, обессилев, но огонь из Хешбона вырвался, из недр Сихона – пламя, чтобы сжечь виски Моава, темя людей хвастливых.","46":"Горе тебе, Моав, гибнет народ Кемоша! Сыновья твои в плен попали, дочери – в неволю.","47":"Но переменю Я участь Моава в дни грядущие, – говорит Господь. Здесь кончается приговор Моаву."},"49":{"1":"О сынах Аммона. Так говорит Господь: разве нет сыновей у Израиля? Разве нет у него наследника? Почему же Милхом завладел Гадом и народ его в городах Гада обитает?","2":"Но настанут дни, – говорит Господь, – когда по воле Моей зазвучат боевые кличи возле Раввы Аммонитской! Станет она грудой развалин, сгорят в огне ее дочери, и будет Израиль властвовать над властителями своими, – говорит Господь. –","3":"Плачь, Хешбон, ибо Ай разграблен! Дочери Раввы, рыдайте, в дерюгу оденьтесь, плачьте, вдоль оград скитайтесь, ибо пойдет Милхом в изгнанье, и жрецы его, и вельможи.","4":"Что долинами своими ты кичишься? Погибла твоя долина! Дочь неверная, на сокровища свои ты уповала: «Кто против меня выступит?»","5":"Я пошлю на тебя ужас, – говорит Господь, Бог Воинств, – со всех сторон! Будете вы изгнаны, рассеяны, и никто не соберет скитальцев обратно.","6":"Но после этого переменю Я участь сынов Аммона, – говорит Господь.","7":"Об Эдоме. Так говорит Господь Воинств: неужели мудрость в Темане иссякла, рассудка не стало у разумных, прогнила их мудрость?","8":"Без оглядки бегите, в пещерах прячьтесь, жители Дедана, ибо Я посылаю беду Исаву, час настал – Я его покараю!","9":"Если бы сборщики винограда к тебе явились, оставили бы они немного ягод. Если бы воры пришли ночью – украли бы, сколько им нужно.","10":"Я же донага оберу Исава, тайники его открою, не сможет он укрыться! Сыновья его ограблены, и братья его, и соседи, нет его больше.","11":"Но оставь своих сирот, и Я сохраню им жизнь, и пусть вдовы твои на Меня уповают!","12":"Так говорит Господь: даже те, кто не заслужил этого, до дна изопьют чашу! Неужели ты избежишь кары? Не избежишь ты кары, до дна изопьешь чашу!","13":"Клянусь Собою, – говорит Господь, – на ужас, позор, опустошение и проклятие обречена Боцра, и все города ее навеки станут руинами.","14":"Весть я слышал от Господа, вестник народам послан: «Собирайтесь, против него идите, на битву вставайте!»","15":"Я сделаю тебя ничтожным средь народов, средь людей – презренным.","16":"На свирепость свою ты понадеялся, на дерзкое свое сердце, о живущий в расселинах скал, горных вершин владыка! Словно орел, ты свил гнездо в вышине, но Я низвергну тебя оттуда, – говорит Господь. –","17":"Эдом обречен на ужас! И всякий, кто пройдет мимо, ужаснется, присвистнет, раны его увидев.","18":"Как на развалинах Содома и Гоморры и городов соседних, – говорит Господь, – так и там человек не поселится, не будут жить люди.","19":"Словно лев, что из зарослей при Иордане на цветущее пастбище вышел, так и Я погоню эдомитян внезапно, нападу на баранов их лучших! Ибо кто Мне подобен, кто Меня призовет к ответу? И какой пастух предо Мною выстоит?","20":"Слушайте, что решил Господь об Эдоме, что задумал Он против жителей Темана! И ягнят утащат из стада, вместе с ними и пастбище Он погубит!","21":"Падет Эдом, и от шума земля содрогнется, донесется крик до Красного моря.","22":"Поднимется орел, на добычу он устремится, над Боцрой раскинет крылья! И в тот день воины Эдома затрепещут, словно роженицы.","23":"О Дамаске. Хамат и Арпад в смятенье, ибо злую весть они услыхали. Мечутся они от страха – так волнуется море, не может стихнуть.","24":"Обессилел Дамаск, обращен в бегство, дрожь его охватила, боль и муки объяли, словно роженицу.","25":"Неужели славный город оставлен, радости моей город?","26":"На улицах его падут юноши, и все воины его в тот день погибнут, – говорит Господь Воинств. –","27":"Я предам огню стены Дамаска, огонь пожрет чертоги Бен – Хадада!","28":"О Кедаре и царствах Хацора, которые сокрушил Навуходоносор, царь Вавилона. Так говорит Господь: против Кедара войной идите, грабьте сынов Востока!","29":"Шатры и стада у них отнимите, заберите полотнища, утварь, верблюдов, кричите им: «Кругом – ужас!»","30":"Бегите, скитайтесь, в пещерах прячьтесь, жители Хацора! – говорит Господь. – Навуходоносор, царь Вавилона, принял о вас решенье, замысел его – против вас!","31":"Идите войною против народа безмятежного, живущего спокойно! – говорит Господь. – Нет у него ни дверей, ни засовов, он живет, не тревожимый никем.","32":"Их верблюды станут чужой добычей, их шумные стада врагам достанутся! По всем ветрам Я рассею тех, кто виски себе бреет, со всех сторон пошлю на них беды, – говорит Господь. –","33":"Станет Хацор приютом шакалов, навеки – пустыней, не поселится там человек, не будут жить люди.","34":"Вот слово Господа об Эламе, которое было пророку Иеремии в начале правления Седекии, царя Иудеи.","35":"Так говорит Господь Воинств: Я сломаю лук Элама, его главную силу!","36":"Я пошлю на Элам четыре ветра с четырех концов неба и развею Элам по ветрам этим. И не будет такого народа, в чью страну не пришли бы изгнанники из Элама.","37":"Я заставлю Элам трепетать перед его врагами, перед теми, кто гибели его жаждет. Я беду на него пошлю, гнев Мой и ярость, – говорит Господь, – гнать его буду мечом, полностью уничтожу!","38":"Престол Мой в Эламе поставлю, истреблю там царя и вельмож, – говорит Господь. –","39":"Но в дни грядущие переменю Я участь Элама, – говорит Господь."},"50":{"1":"Слово о Вавилоне, о земле халдейской, которое Господь возвестил через пророка Иеремию.","2":"Возвестите народам, расскажите, знак подайте, расскажите, не скрывайте, говорите так: «Взят Вавилон! Бел опозорен, Мардук повержен – осквернены изваяния вавилонские, идолы его разбиты».","3":"Северный народ против Вавилона вышел, страну вавилонскую он обратит в пустыню. Не останется там ни человека, ни зверя, уйдут они, будут скитаться.","4":"В те дни, в то время, – говорит Господь, – придут сыны Израиля и сыны Иуды, пойдут они с плачем, искать будут Господа, своего Бога.","5":"К Сиону будут искать дорогу, к нему обратят лица: «Пойдемте, с Господом соединимся договором вечным, который забыт не будет!»","6":"Народ Мой – потерянные овцы, по вине пастухов они блуждают, кружат средь гор. По горам, по холмам они ходят, пристанище свое позабыли.","7":"Всякий встречный их пожирает, говорят их враги: «Мы невиновны! Ведь пред Господом они согрешили, пред обителью правды, пред Господом – надеждой отцов их!»","8":"Из Вавилона бегите, из земли халдейской уходите, вожаками будьте для стада!","9":"Ибо Я приведу из земли северной собранье великих народов, против Вавилона пошлю их – они его осадят, и будет он захвачен. Стрелы их – стрелы искусного воина, что не возвращается без добычи.","10":"Халдея разграблена будет, и грабитель насытится! – говорит Господь.","11":"Веселитесь вы, ликуете, грабите Мой удел! Словно бык на лугу, вы резвитесь, словно жеребцы, ржете!","12":"Но будет ваша мать опозорена, родительница ваша – поругана, станет она последней средь народов, пустыней будет, пустошью безводной.","13":"Из-за гнева Господнего жителей она лишится, превратится в сплошную пустыню. И всякий, кто пройдет мимо Вавилона, ужаснется, присвистнет, раны его увидев.","14":"Окружайте эту столицу, лучники, стреляйте в нее, стрел не жалейте, ибо пред Господом она согрешила!","15":"Со всех сторон кричите! Просит она о пощаде, ее башни пали, рухнули стены – это мщенье Господа! Мстите ей! Что она творила, то и с ней творите!","16":"Земледельцев вавилонских истребите, тех, кто в жатву серп берет в руки! Пред мечом жестоким каждый к своему народу устремится, побежит на свою землю.","17":"Израиль – стадо овец рассеянное, львы его гнали! Царь Ассирии пожирал его сначала, глодал потом кости Навуходоносор, царь Вавилона.","18":"Так говорит Господь Воинств, Бог Израиля: Я покараю царя вавилонского и его страну, как покарал Я царя Ассирии.","19":"Я верну Израиль на прежнее пастбище, будет он пастись на Кармиле и в Башане, на горах Ефрема и Галаада он насытится.","20":"В те дни, в то время, – говорит Господь, – будут искать преступленье Израиля, но тщетно, будут искать грех Иуды, но не найдут, ибо тех, кого Я оставлю в живых, Я прощу.","21":"Иди войной на страну Мератаим, против жителей Пекода, убей, истреби их всех до последнего, – говорит Господь. – Сделай то, что Я тебе заповедал!","22":"На земле этой – шум сражений, великое разрушенье!","23":"О, разбит, расколот молот, дробивший всю землю! Пустыней стал Вавилон средь народов.","24":"Против тебя Я раскинул сети, и ты, Вавилон, попался – разве мог ты это предвидеть' Ты застигнут и схвачен, ибо с Господом ты сражался.","25":"Открыл Господь Свое хранилище, взял орудия гнева: будет работа у Господа, Бога Воинств, на земле халдеев!","26":"Со всех сторон на нее идите, житницы ее откройте, собирайте добро ее в груды, до конца ее уничтожьте, чтобы ничего на ней не осталось!","27":"Всех быков ее убейте, пусть идут они на закланье. Горе им, день их настал, час расплаты!","28":"Слышен крик беженцев, спасшихся из земли вавилонской, и теперь на Сионе узнают, что отомстил Господь, Бог наш, отомстил за Храм Свой.","29":"Лучников против Вавилона созовите! Окружите его, осадите, лучники, пусть никто не спасется бегством! По заслугам ему отплатите, что творил он, то и с ним творите, ибо против Господа он возносился, против Святого Израилева.","30":"На улицах его падут юноши, и все воины его в тот день погибнут, – говорит Господь.","31":"Я иду против тебя, Гордец, – говорит Господь, Бог Воинств, – ибо день твой настал, час, когда Я тебя покараю!","32":"Споткнется, падет Гордец, и никто его не поднимет. Его города Я предам огню, и огонь все вокруг поглотит!","33":"Так говорит Господь Воинств: притесняют сынов Израиля и сынов Иуды! Взяли их в плен, в плену держат, отпустить не желают.","34":"Но силен их Избавитель, Его имя – Господь Воинств! Он заступится за них и землю их успокоит, а жителей Вавилона лишит покоя.","35":"Меч занесен над халдеями, – говорит Господь, – над жителями Вавилона, над вельможами его и мудрецами!","36":"Меч занесен над его гадателями, потому они обезумеют, меч – над воинами его, потому они затрепещут,","37":"меч – над конями его и колесницами, над смешеньем народов, что в нем обитают, потому они станут как женщины. Меч занесен над его сокровищами, потому их разграбят,","38":"засуха придет на его воды, и воды иссякнут, ибо это земля истуканов! Из-за идолов жители ее обезумели.","39":"Будут жить там шакалы и звери пустыни, будут жить там совы, навеки земля эта станет безлюдной, из рода в род – необитаемой.","40":"Как в Содоме и Гоморре и в городах соседних, разрушенных Богом, – говорит Господь, – так и там человек не поселится, не будут жить люди.","41":"Идет народ с севера, могучее племя, цари великие – от края земли они поднимаются!","42":"Лук и меч они держат, жестоки они, беспощадны, их крики – как рокот моря. Скачут они на конях, воины, готовые к битве, – против тебя, дочь Вавилона!","43":"Услыхал о них царь Вавилона, и руки его опустились, боль пронзила его и мука, словно роженицу.","44":"Словно лев, что из зарослей при Иордане на цветущее пастбище вышел, так и Я погоню вавилонян внезапно, нападу на баранов их лучших! Ибо кто Мне подобен, кто Меня призовет к ответу? И какой пастух предо Мною выстоит?","45":"Слушайте, что решил Господь о Вавилоне, что задумал Он против страны халдеев! И ягнят утащат из стада, вместе с ними и пастбище Он погубит!","46":"Будет взят Вавилон, и от шума земля содрогнется, все народы крик услышат."},"51":{"1":"Так говорит Господь: подниму Я против Вавилона, против жителей Лев – Камая, гибельный ветер!","2":"Я пошлю на Вавилон чужеземцев, и они его по ветру развеют, опустошат его землю, окружат отовсюду в день бедствия.","3":"На него пусть лучник лук нацелит, пусть броню наденет. Юношей его не щадите, всех воинов его перебейте!","4":"Пусть лежат убитые на земле халдейской, пронзенные – на улицах Вавилона!","5":"Ибо Израиль и Иуда не брошены Богом их, Господом Воинств, хоть земля их полна грехами пред Святым Израилевым.","6":"Из Вавилона бегите, жизнь свою спасайте, чтобы не погибнуть за преступления Вавилона, ибо пришло время мщенья Господнего. Он сполна Вавилону отплатит!","7":"Вавилон – золотая чаша в руках Господних. Всю землю она опьяняла, пили из нее вино народы, и стали народы безумны.","8":"Но пал Вавилон внезапно, разбился! Над ним рыдайте, бальзам для ран его принесите – может, он исцелится.","9":"«Вавилон мы лечили, он не излечился». – «Оставьте его, пойдемте каждый в свою землю, ибо суд над Вавилоном достиг неба, до облаков поднялся».","10":"«Оправдал нас Господь! Пойдем, возвестим на Сионе дела Господа, нашего Бога».","11":"Стрелы точите, колчан наполняйте! Пробудил Господь дух царей мидийских. Его замысел – против Вавилона: Вавилон уничтожить! Ибо отомстит Господь, отомстит за Храм Свой.","12":"Против стен Вавилона поднимите знамя, усильте стражу, стражников расставьте, засады устройте! Что задумал Господь, то Он и сделает – все, что предрек Он жителям Вавилона, то Он исполнит.","13":"Ты живешь при водах великих, великими сокровищами владеешь, но близка твоя гибель, твоих грабежей конец!","14":"Господь Воинств поклялся Собою: «Словно саранчой, людьми тебя наполню, их победный крик над тобой раздастся!»","15":"Могуществом Своим сотворил Он землю, утвердил вселенную мудростью Своею, разумом Своим распростер небо!","16":"Возвысит Он голос – соберутся, зашумят на небесах воды. От края земли Он тучи поднимает, творит Он молнии грозовые и выводит ветер из Своих хранилищ.","17":"Глуп человек без знания, на позор себе мастер идолов выплавляет, ибо изваяния его литые – ложь, нет в них духа.","18":"Ничтожны они, смехотворные поделки, в час расплаты они сгинут.","19":"Но не таков Он, Удел Иакова: всему Он дал облик, Израиль – племя Его и владенье, Его имя – Господь Воинств!","20":"Ты молот Мой, войны орудье, Я сокрушал тобою народы, уничтожал царства.","21":"Я сокрушал тобою коня и всадника, сокрушал тобою колесницу и колесничего.","22":"Я сокрушал тобою мужчину и женщину, сокрушал тобою старика и ребенка, сокрушал тобою юношу и деву.","23":"Я сокрушал тобою пастуха и стадо, сокрушал тобою земледельца с волами, сокрушал тобою владык и наместников.","24":"Но у вас на глазах Я отплачу Вавилону, всем жителям Халдеи за все зло, какое они сотворили на Сионе, – говорит Господь.","25":"Я иду против тебя, о Гора погибели! – говорит Господь. – Ты губила всю землю, и теперь Я руку на тебя простираю. Я низвергну тебя со скал, сделаю тебя горой обугленной.","26":"Не возьмут у тебя камней для стен, камней для основанья, ты станешь пустыней навеки, – говорит Господь. –","27":"Поднимайте по всей земле знамена, средь народов в рог трубите, на войну с Вавилоном освятите народы, созовите против него царства – Арарат, Минни, Ашкеназ – полководца против него пошлите, коней соберите, что тучу саранчи!","28":"На войну с Вавилоном освятите народы, царей Мидии, владык ее и наместников, всю подвластную им землю.","29":"Содрогнулась земля, задрожала, ибо исполнился замысел Господа о Вавилоне – стала земля Вавилона пустыней безлюдной!","30":"Воины вавилонские сражаться перестали, сидят они в крепостях, сила их истощилась, стали они как женщины. Дома Вавилона пылают, засовы сбиты.","31":"Пусть бежит гонец гонцу навстречу, вестник – к вестнику, пусть возвестят царю Вавилона, что весь город его захвачен,","32":"переправы взяты, укрепленья огнем пылают, воины – в страхе.","33":"Так говорит Господь Воинств, Бог Израиля: о дочь Вавилона! Она – словно ток молотильный, когда его топчут. Еще немного – и время жатвы для нее наступит.","34":"Пожрал, погубил меня Навуходоносор, царь Вавилона, сделал меня пустым сосудом! Он, словно чудище, проглотил меня, насладился мною, набил себе брюхо, а потом меня извергнул.","35":"«Вавилон терзал мое тело!» – скажет жительница Сиона. «Кровь моя – на жителях Халдеи!» – скажет Иерусалим.","36":"Так говорит Господь: Я заступлюсь за тебя, за тебя отомщу, осушу их море, их источники лишу воды!","37":"Будет Вавилон грудой камня, приютом шакалов, обречен он на ужас и униженье, жителей в нем не останется.","38":"Рычат они, словно львы, ревут, словно львята.","39":"Но станет им жарко, и Я дам им напиться, допьяна напою их, чтобы они веселились, а потом уснули сном вечным, от которого они не пробудятся, – говорит Господь. –","40":"Я погоню их, как овец, на закланье, как баранов с козлами!","41":"О, взят Шешах, слава всей земли захвачена! Пустыней стал Вавилон средь народов.","42":"Море поднялось над Вавилоном, волны шумные Вавилон сокрыли.","43":"Города его стали ужасом, сухой землей и пустыней, землей, где не будут селиться люди, где человек ходить не будет.","44":"Я покараю Бела вавилонского, то, что он поглотил, из уст его вырву, и не будут больше стекаться к нему народы. Падет стена Вавилона!","45":"Мой народ, уходи оттуда! Жизни свои спасайте от яростного гнева Господнего.","46":"Пусть сердце ваше не замирает, не пугайтесь слухов, что по земле разносятся. В один год приходят слухи, в другой год – опять слухи: «На земле – насилье, владыка – против владыки!»","47":"Дни настанут, Я покараю идолов вавилонских! Вся земля его будет поругана, лежать на ней будут убитые.","48":"Земля и небо возликуют и все, что есть на земле и небе, ибо с севера придут в Вавилон опустошители, – говорит Господь. –","49":"О вы, израильтяне убитые! Падет Вавилон, ведь по всей земле падали убитые Вавилоном.","50":"О вы, меча избежавшие! Идите, не стойте, о Господе вспомните в стране далекой, пусть Иерусалим будет в вашем сердце.","51":"Опозорены мы, поношения слышим, стыд покрыл наши лица, ведь вошли чужеземцы в святой Храм Господа.","52":"Дни настанут, – говорит Господь, – Я покараю идолов Вавилона, по всей земле его стонать будут раненые.","53":"До небес Вавилон возвысился, высоко вознес свою силу, но по воле Моей придут к нему опустошители, – говорит Господь.","54":"Рыданья из Вавилона раздаются, в земле халдеев – великое разрушенье!","55":"Это Господь опустошает Вавилон, Он заставит умолкнуть голос громкий вавилонян. Шумят их волны, бурные воды, голос их рокочет!","56":"На Вавилон идет опустошитель, воины вавилонские будут взяты в плен, луки их будут сломаны, ибо Господь – Бог воздаянья, Он воздаст, отплатит!","57":"Я напою допьяна вельмож его и мудрецов, владык, наместников, воинов, уснут они сном вечным, от которого они не пробудятся, – говорит Царь, чье имя Господь Воинств.","58":"Так говорит Господь Воинств: толстые стены Вавилона до основанья будут разрушены, высокие его ворота сгорят в огне. Понапрасну народы трудились, племена из сил выбивались. Все сожжено будет!","59":"Вот что повелел пророк Иеремия Серае, сыну Нерии, сына Махсеи, когда тот отправился в Вавилон вместе с Седекией, царем Иудеи, в четвертый год правления Седекии (Серая был главным постельничим).","60":"Иеремия записал в отдельный свиток все беды, которые должны были случиться с Вавилоном, – все, что написано здесь о Вавилоне.","61":"И сказал Иеремия Серае: «Когда ты придешь в Вавилон, посмотри на него и прочти все эти слова.","62":"И скажи: „Ты, о Господь, решил уничтожить это место, и не будет здесь жителей, ни человека, ни зверя, станет оно пустыней навеки!\"","63":"И как только ты прочтешь этот свиток, привяжи к нему камень, брось в Евфрат","64":"и скажи: „Так и Вавилон утонет! Не поднимется он после той беды, которую Я пошлю на него, лишится сил\"». Здесь кончаются слова Иеремии."},"52":{"1":"Двадцать один год было Седекии, когда он стал царем; одиннадцать лет царствовал он в Иерусалиме; имя его матери – Хамуталь, дочь Иеремии, из Ливны .","2":"Его дела были так же ненавистны Господу, как и дела Иоакима.","3":"Гнев Господень против Иерусалима и Иудеи был столь силен, что Господь отверг их и отвернулся от них. И Седекия восстал против царя вавилонского.","4":"В девятый год царствования Седекии, в десятый день десятого месяца, Навуходоносор, царь Вавилона, со всем своим войском подошел к Иерусалиму. Он осадил город и окружил его валом.","5":"Осада продолжалась до одиннадцатого года царствова – ния Седекии.","6":"В девятый день четвертого месяца (в городе в это время свирепствовал голод, народу нечего было есть)","7":"городская стена была проломлена. Все воины бежали – ночью они вышли из города через Ворота Двух Стен, что у царского сада (а город в то время был окружен халдеями), и пошли по дороге на Араву.","8":"Войско халдеев пустилось в погоню за царем и настигло Седекию в пустыне близ Иерихона. Все воины царя разбежались,","9":"а его самого схватили и привели к царю Вавилона в Ривлу, что в земле Хамат, и там Навуходоносор устроил над ним суд.","10":"На глазах у Седекии царь Вавилона убил его сыновей, и всех вельмож Иудеи перебил он в Ривле.","11":"Затем он ослепил Седекию и заковал его в кандалы. И увел его царь вавилонский в Вавилон и держал его в тюрьме до самой смерти.","12":"В десятый день пятого месяца, в девятнадцатый год правления Навуходоносора, царя вавилонского, в Иерусалим пришел Навузарадан, начальник телохранителей, один из приближенных вавилонского царя.","13":"Он сжег Храм Господа, царский дворец и все дома в Иерусалиме – все большие здания он сжег дотла.","14":"И крепостные стены вокруг Иерусалима тоже разрушили халдейские воины Навузардана.","15":"Некоторых бедняков и всех, кто еще уцелел в городе, включая перебежчиков, перешедших к вавилонскому царю, – всех Навузарадан, начальник телохранителей, отправил в Вавилон.","16":"Лишь самую бедноту Навузарадан, начальник телохранителей, оставил в стране – работать в виноградниках и на полях.","17":"Медные столбы из Храма Господа, и подставки, и медное море, что в Храме Господа, халдеи разломали, а медь увезли в Вавилон.","18":"Взяли они и котлы, и совки, щипцы, и чаши для кропления, и ковши – всю медную утварь, которая использовалась при богослужении.","19":"Взял начальник телохранителей и чаны, и кадильницы, и чаши для кропления, и котлы, и светильники, и ковши и сосуды для возлияний, и все золото, и все серебро.","20":"Две колонны и одно медное море, двенадцать медных быков под морем и подставки (все это сделал для Храма Господнего царь Соломон), столько было меди во всем этом, не счесть!","21":"Каждая колонна была восемнадцати локтей в высоту, в обхват – двенадцать локтей. Были они полыми, толщина стенок – четыре пальца.","22":"У каждой – медная капитель высотой в пять локтей. Вокруг капителей у обеих колонн – сетка с плодами граната, все из меди.","23":"По сторонам было девяносто шесть гранатов, всего же вокруг сетки – сто.","24":"Начальник телохранителей увел в плен первосвященника Сераю, второго священника Софонию и трех стражей ворот.","25":"Он также забрал из города сановника, который командовал воинами, семь человек из свиты царя, которых нашел в городе, писца, который начальствовал над войском и занимался набором ополчения, и еще шестьдесят знатных людей, которых нашел в городе.","26":"Навузарадан, начальник телохранителей, привел их к царю Вавилона в Ривлу.","27":"И там, в Ривле, что в стране Хамат, царь казнил их всех. Так иудеи были выселены со своей земли.","28":"Вот сколько всего людей угнал Навуходоносор: в седьмой год – три тысячи двадцать три иудея;","29":"в восемнадцатый год правления Навуходоносора из Иерусалима было угнано восемьсот тридцать два человека;","30":"в двадцать третий год правления Навуходоносора Навузарадан, начальник телохранителей, угнал семьсот сорок пять иудеев. Всего – четыре тысячи шестьсот человек.","31":"В тридцать седьмой год после пленения Иехонии, царя Иудеи, в двадцать пятый день двенадцатого месяца, Эвил – Меродах, ставший в тот год царем Вавилона, помиловал Иехонию, царя Иудеи, и освободил его из тюрьмы.","32":"Он говорил с ним дружелюбно, велел ему сидеть выше всех остальных царей, которые были при Эвил – Меродахе в Вавилоне,","33":"и приказал дать ему новую одежду, вместо прежней, что была на нем в тюрьме. С тех пор и до конца дней своих Иехония ел за столом царя вавилонского.","34":"И он получал постоянное содержание от вавилонского царя – ежедневно, до самой смерти, до конца дней своих."}};
